values ('3e75ab17-f401-7c7f-bcfa-c555b493a788', 'about', 'about-1', 'قرية أبو بدوي', null, 'قريـة أبو بدوي (وتُعرف أيضاً بعزبة بدوي) هي قرية تتبع إدارياً لـ مركز بيلا في محافظة كفر الشيخ بجمهورية مصر العربية. معلومات أساسية عن القرية • الموقع: تقع في مركز بيلا التابع لمحافظة كفر الشيخ في دلتا مصر. • السكان: بلغ إجمالي عدد سكانها نحو 8,698 نسمة حسب الإحصاء الرسمي لعام 2006 (منهم 4,284 رجلاً و4,414 امرأة)   
المصدر : <a href="https://ar.wikipedia.org/wiki/%D8%A8%D8%AF%D9%88%D9%8A_(%D8%B9%D8%B2%D8%A8%D8%A9)" rel="noopener noreferrer nofollow" target="_blank" title="https://ar.wikipedia.org/wiki/%D8%A8%D8%AF%D9%88%D9%8A_(%D8%B9%D8%B2%D8%A8%D8%A9)">بدوي (عزبة) - ويكيبيديا</a>', 'https://hrsrtvrrpnwxqhadxhfg.supabase.co/storage/v1/object/public/media/about/da296c59-e41f-41dd-80a1-79e138948267/Screenshot-2026-10-03-232256.png', 'تصميم توضيحي — حر الاستخدام (CC0)', null, null, null, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true, true, 'published', '2026-10-03', '2026-10-03T00:00:00.000Z'::timestamptz, 1)
on conflict (id) do nothing;
insert into public.items (id, section_id, slug, title, subtitle, body, image, image_credit, link,
                          source_name, source_url, tags, fields, attachments, pinned, breaking,
                          status, event_date, published_at, sort_order)
values ('af7ba1a2-224e-8bc5-83e3-3a545a8be2d5', 'governorate', 'gov-facts', 'بطاقة سريعة عن المحافظة', 'أرقام ويكيبيديا في قائمة واحدة، ومصدر كل رقم مذكور', '<p>خلاصة الأرقام التي وردت في مقالة <a href="https://ar.wikipedia.org/wiki/%D9%85%D8%AD%D8%A7%D9%81%D8%B8%D8%A9_%D9%83%D9%81%D8%B1_%D8%A7%D9%84%D8%B4%D9%8A%D8%AE" rel="noopener noreferrer nofollow" target="_blank">محافظة كفر الشيخ</a>:</p><ul><li>العاصمة وأكبر المدن: مدينة كفر الشيخ.</li><li>المساحة: 3,466.7 كم² (825.1 ألف فدان) — 28.1% من إقليم الدلتا.</li><li>السكان: 3,740,624 نسمة بتقدير 1/1/2024 (الجهاز المركزي للتعبئة العامة والإحصاء).</li><li>الكثافة: 846.5 نسمة/كم² (2015).</li><li>العشرة مراكز والثلاث عشرة مدينة (14 في صندوق المعلومات) و44 وحدة محلية قروية و2,801 تجمع ريفي.</li><li>تأسيسها ككيان إداري منفصل: 1949 (مديرية الفؤادية)، ومحافظة منذ 1960.</li><li>العيد القومي: 4 نوفمبر (ذكرى معركة البرلس 1956).</li><li>أسماء سابقة: مديرية الفؤادية ثم مديرية كفر الشيخ.</li><li>رمز الهاتف: 047، والتوقيت: GMT+2.</li><li>الموقع الرسمي (كما وثّقته ويكيبيديا): <a href="https://web.archive.org/web/20170914094432/http://kafrelsheikh.gov.eg/" rel="noopener noreferrer nofollow" target="_blank">نسخة مؤرشفة من kafrelsheikh.gov.eg</a>.</li></ul><p><strong>المصدر:</strong> ويكيبيديا العربية، مقالة محافظة كفر الشيخ — نصها مرخّص CC BY-SA 4.0 (<a href="https://creativecommons.org/licenses/by-sa/4.0/deed.ar" rel="noopener noreferrer nofollow" target="_blank">رخصة المشاع الإبداعي</a>)، وصور هذا القسم من ويكيميديا كومنز برخصة حرة مع ذكر المرخّص تحت كل صورة.</p>', null, null, 'https://ar.wikipedia.org/wiki/%D9%85%D8%AD%D8%A7%D9%81%D8%B8%D8%A9_%D9%83%D9%81%D8%B1_%D8%A7%D9%84%D8%B4%D9%8A%D8%AE', 'ويكيبيديا العربية (CC BY-SA 4.0)', 'https://ar.wikipedia.org/wiki/%D9%85%D8%AD%D8%A7%D9%81%D8%B8%D8%A9_%D9%83%D9%81%D8%B1_%D8%A7%D9%84%D8%B4%D9%8A%D8%AE', '["بطاقة","أرقام","مصادر"]'::jsonb, '{"الكثافة":"846.5 نسمة/كم²","المساحة":"3,466.7 كم²","السكان (2024)":"3,740,624 نسمة","العيد القومي":"4 نوفمبر"}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-04', '2026-10-04T00:00:00.000Z'::timestamptz, 20)
