values ('21477de8-cbb0-4049-a384-05f763bf9f7c', 'governorate', 'gov-beela', 'مركز بيلا وموقع قريتنا', 'أحد عشرة مراكز المحافظة، وفيه 12 وحدة محلية و262 قرية وعزبة', '<p>مركز بيلا أحد المراكز العشرة في محافظة كفر الشيخ، وقاعدته مدينة بيلا، وفيه 12 وحدة محلية تضم 262 قرية وعزبة بحسب التقسيم الوارد في مقالة المحافظة. وقد أُلحق بمأمورية كفر الشيخ في 16 أكتوبر 1938 بعد إنشائه في العام نفسه فصلًا عن مديرية الغربية، ثم بقي ضمن الكيان الذي صار محافظة كفر الشيخ سنة 1960.</p><p>وقريتنا — أبو بدوي وتُعرف أيضًا بعزبة بدوي — تتبع إداريًا مركز بيلا في محافظة كفر الشيخ، كما هو مثبت في قسم «التعريف بالقرية» في هذا التطبيق؛ وبلغ إجمالي عدد سكانها نحو 8,698 نسمة في الإحصاء الرسمي لعام 2006 (4,284 رجلًا و4,414 امرأة) بحسب مقالة «بدوي (عزبة)» في ويكيبيديا.</p><p><strong>المصادر:</strong> ويكيبيديا العربية، مقالات <a href="https://ar.wikipedia.org/wiki/%D9%85%D8%B1%D9%83%D8%B2_%D8%A8%D9%8A%D9%84%D8%A7" rel="noopener noreferrer nofollow" target="_blank">مركز بيلا</a> و<a href="https://ar.wikipedia.org/wiki/%D8%A8%D8%AF%D9%88%D9%8A_(%D8%B9%D8%B2%D8%A8%D8%A9)" rel="noopener noreferrer nofollow" target="_blank">بدوي (عزبة)</a> و<a href="https://ar.wikipedia.org/wiki/%D9%85%D8%AD%D8%A7%D9%81%D8%B8%D8%A9_%D9%83%D9%81%D8%B1_%D8%A7%D9%84%D8%B4%D9%8A%D8%AE" rel="noopener noreferrer nofollow" target="_blank">محافظة كفر الشيخ</a>.</p>', null, null, 'https://ar.wikipedia.org/wiki/%D9%85%D8%B1%D9%83%D8%B2_%D8%A8%D9%8A%D9%84%D8%A7', 'ويكيبيديا العربية (CC BY-SA 4.0)', 'https://ar.wikipedia.org/wiki/%D9%85%D8%B1%D9%83%D8%B2_%D8%A8%D9%8A%D9%84%D8%A7', '["مركز بيلا","أبو بدوي","تقسيم إداري"]'::jsonb, '{"القرى والعزب":"262","أبو بدوي تتبع":"مركز بيلا","الوحدات المحلية":"12 وحدة"}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-04', '2026-10-04T00:00:00.000Z'::timestamptz, 17)
