values ('4416b306-5719-94af-09b3-49c98692e195', 'governorate', 'gov-university', 'التعليم العالي: جامعة كفر الشيخ', 'قرار جمهوري رقم 129 لسنة 2006 فصلها عن جامعة طنطا', '<p>تعد جامعة كفر الشيخ أحد أهم المؤسسات التعليمية في المحافظة، وهي جامعة حكومية مصرية بدأت فرعًا لجامعة طنطا حتى استقلت عنها بموجب القرار الجمهوري رقم (129) لسنة (2006) — وهو القرار نفسه الذي أنشئت بموجبه جامعة سوهاج.</p><p>وتتبع المقالة جذورها: حجر الأساس كان بتأسيس المعهد العالي الزراعي في مدينة كفر الشيخ عام 1957 تابعًا لوزارة التعليم العالي، ثم تحوّل إلى كلية الزراعة عام 1969 بتبعية لجامعة الإسكندرية، وانتقلت تبعيتها إلى جامعة طنطا عند إنشائها عام 1973. وأنشئت كلية التربية عام 1977، ثم فرع لجامعة طنطا بالمدينة عام 1983، فتوالى إنشاء الكليات: الطب البيطري 1985، والتربية النوعية 1988 (تحولت تبعيتها إلى طنطا بالقرار الوزاري 1187 لسنة 1991)، والتجارة والهندسة 1990، والآداب 1993، والتربية الرياضية 1997.</p><p>وبعد الاستقلال توالت افتتاح الكليات حتى أصبحت الجامعة تضم تسع عشرة كلية وثلاثة معاهد. ولجامعة الأزهر أيضًا كليات بمدينتي كفر الشيخ ودسوق، منها كلية الدراسات الإسلامية والعربية بدسوق، وفي دسوق ستة معاهد أزهرية بمراحلها الثلاثة.</p><p><strong>المصدر:</strong> ويكيبيديا العربية، مقالات <a href="https://ar.wikipedia.org/wiki/%D8%AC%D8%A7%D9%85%D8%B9%D8%A9_%D9%83%D9%81%D8%B1_%D8%A7%D9%84%D8%B4%D9%8A%D8%AE" rel="noopener noreferrer nofollow" target="_blank">جامعة كفر الشيخ</a> و<a href="https://ar.wikipedia.org/wiki/%D9%85%D8%AD%D8%A7%D9%81%D8%B8%D8%A9_%D9%83%D9%81%D8%B1_%D8%A7%D9%84%D8%B4%D9%8A%D8%AE" rel="noopener noreferrer nofollow" target="_blank">محافظة كفر الشيخ</a> و<a href="https://ar.wikipedia.org/wiki/%D8%AF%D8%B3%D9%88%D9%82" rel="noopener noreferrer nofollow" target="_blank">دسوق</a>.</p>', null, null, 'https://ar.wikipedia.org/wiki/%D8%AC%D8%A7%D9%85%D8%B9%D8%A9_%D9%83%D9%81%D8%B1_%D8%A7%D9%84%D8%B4%D9%8A%D8%AE', 'ويكيبيديا العربية (CC BY-SA 4.0)', 'https://ar.wikipedia.org/wiki/%D8%AC%D8%A7%D9%85%D8%B9%D8%A9_%D9%83%D9%81%D8%B1_%D8%A7%D9%84%D8%B4%D9%8A%D8%AE', '["جامعة","تعليم عالي","كليات"]'::jsonb, '{"اليوم":"19 كلية و3 معاهد","النشأة":"1957 المعهد العالي الزراعي","فرع لطنطا":"1983","استقلالها":"القرار 129 لسنة 2006"}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-04', '2026-10-04T00:00:00.000Z'::timestamptz, 10)
