values ('4e06cd8b-2cf6-1126-c976-de4f33ee7678', 'local_news', 'rss-8a1253367acb', 'تحرك عراقي في حقل "أبو خيمة" النفطي قرب السعودية والكويت... ما هي الفوائد والتحديات؟', 'يكثّف العراق أعمال الاستكشاف في حقل "أبو خيمة" بمحافظة المثنى قرب الحدود مع السعودية والكويت، تمهيدًا لتقييم إمكاناته النفطية واتخاذ قرارات بشأن تطويره واستثمار موارده.', '<p>يكثّف العراق أعمال الاستكشاف في حقل "أبو خيمة" بمحافظة المثنى قرب الحدود مع السعودية والكويت، تمهيدًا لتقييم إمكاناته النفطية واتخاذ قرارات بشأن تطويره واستثمار موارده.</p>', null, null, 'https://sarabic.ae/20261012/%D8%AA%D8%AD%D8%B1%D9%83-%D8%B9%D8%B1%D8%A7%D9%82%D9%8A-%D9%81%D9%8A-%D8%AD%D9%82%D9%84-%D8%A3%D8%A8%D9%88-%D8%AE%D9%8A%D9%85%D8%A9-%D8%A7%D9%84%D9%86%D9%81%D8%B7%D9%8A-%D9%82%D8%B1%D8%A8-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-%D9%88%D8%A7%D9%84%D9%83%D9%88%D9%8A%D8%AA-%D9%85%D8%A7-%D9%87%D9%8A-%D8%A7%D9%84%D9%81%D9%88%D8%A7%D8%A6%D8%AF-%D9%88%D8%A7%D9%84%D8%AA%D8%AD%D8%AF%D9%8A%D8%A7%D8%AA-1117723586.html', 'سبوتنيك عربي', 'https://sarabic.ae/20261012/%D8%AA%D8%AD%D8%B1%D9%83-%D8%B9%D8%B1%D8%A7%D9%82%D9%8A-%D9%81%D9%8A-%D8%AD%D9%82%D9%84-%D8%A3%D8%A8%D9%88-%D8%AE%D9%8A%D9%85%D8%A9-%D8%A7%D9%84%D9%86%D9%81%D8%B7%D9%8A-%D9%82%D8%B1%D8%A8-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-%D9%88%D8%A7%D9%84%D9%83%D9%88%D9%8A%D8%AA-%D9%85%D8%A7-%D9%87%D9%8A-%D8%A7%D9%84%D9%81%D9%88%D8%A7%D8%A6%D8%AF-%D9%88%D8%A7%D9%84%D8%AA%D8%AD%D8%AF%D9%8A%D8%A7%D8%AA-1117723586.html', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-12', '2026-10-12T00:00:00.000Z'::timestamptz, 16)
