values ('a62f2ccb-4e30-64f2-c318-4495ab19f37e', 'local_news', 'rss-65338505628f', 'تقرير: مصافي النفط الأمريكية تجني مليارات الدولارات من اضطراب إمدادات الطاقة العالمية', 'تستعد أكبر شركات تكرير النفط في الولايات المتحدة الأمريكية لتحقيق نتائج مالية قياسية بنهاية الربع الثالث، ووفقًا لتقارير أمريكية، فإن المنتجين المستقلين "فاليرو إنرجي" و"ماراثون بتروليوم" و"فيليبس 66" قد يتجاوزون النتائج التي تم تسجيلها في', '<p>تستعد أكبر شركات تكرير النفط في الولايات المتحدة الأمريكية لتحقيق نتائج مالية قياسية بنهاية الربع الثالث، ووفقًا لتقارير أمريكية، فإن المنتجين المستقلين "فاليرو إنرجي" و"ماراثون بتروليوم" و"فيليبس 66" قد يتجاوزون النتائج التي تم تسجيلها في يونيو/ حزيران.</p>', 'https://cdn.img.sarabic.ae/img/101343/39/1013433914_0:0:3000:1688_600x0_80_0_0_7d657b45d4202473c1091ee322814d6b.jpg', 'الصورة من سبوتنيك عربي', 'https://sarabic.ae/20261009/%D8%AA%D9%82%D8%B1%D9%8A%D8%B1-%D9%85%D8%B5%D8%A7%D9%81%D9%8A-%D8%A7%D9%84%D9%86%D9%81%D8%B7-%D8%A7%D9%84%D8%A3%D9%85%D8%B1%D9%8A%D9%83%D9%8A%D8%A9-%D8%AA%D8%AC%D9%86%D9%8A-%D9%85%D9%84%D9%8A%D8%A7%D8%B1%D8%A7%D8%AA-%D8%A7%D9%84%D8%AF%D9%88%D9%84%D8%A7%D8%B1%D8%A7%D8%AA-%D9%85%D9%86-%D8%A7%D8%B6%D8%B7%D8%B1%D8%A7%D8%A8-%D8%A5%D9%85%D8%AF%D8%A7%D8%AF%D8%A7%D8%AA-%D8%A7%D9%84%D8%B7%D8%A7%D9%82%D8%A9-%D8%A7%D9%84%D8%B9%D8%A7%D9%84%D9%85%D9%8A%D8%A9-1117666021.html', 'سبوتنيك عربي', 'https://sarabic.ae/20261009/%D8%AA%D9%82%D8%B1%D9%8A%D8%B1-%D9%85%D8%B5%D8%A7%D9%81%D9%8A-%D8%A7%D9%84%D9%86%D9%81%D8%B7-%D8%A7%D9%84%D8%A3%D9%85%D8%B1%D9%8A%D9%83%D9%8A%D8%A9-%D8%AA%D8%AC%D9%86%D9%8A-%D9%85%D9%84%D9%8A%D8%A7%D8%B1%D8%A7%D8%AA-%D8%A7%D9%84%D8%AF%D9%88%D9%84%D8%A7%D8%B1%D8%A7%D8%AA-%D9%85%D9%86-%D8%A7%D8%B6%D8%B7%D8%B1%D8%A7%D8%A8-%D8%A5%D9%85%D8%AF%D8%A7%D8%AF%D8%A7%D8%AA-%D8%A7%D9%84%D8%B7%D8%A7%D9%82%D8%A9-%D8%A7%D9%84%D8%B9%D8%A7%D9%84%D9%85%D9%8A%D8%A9-1117666021.html', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-09', '2026-10-09T00:00:00.000Z'::timestamptz, 15)
