values ('9d6472bf-ce39-044f-2c47-e67a26f3fc83', 'local_news', 'rss-85ad245d35b2', 'خطأ فادح من مصطفى شوبير يمنح جنوب إفريقيا التقدم أمام مصر', 'انتزع منتخب جنوب إفريقيا هدف التقدم على مضيفه المصري بهدف دون رد، في مواجهة المنتخبين الودية على أرضية ستاد القاهرة الدولي، إثر استغلال هفوة حارس المرمى مصطفى شوبير.', '<p>انتزع منتخب جنوب إفريقيا هدف التقدم على مضيفه المصري بهدف دون رد، في مواجهة المنتخبين الودية على أرضية ستاد القاهرة الدولي، إثر استغلال هفوة حارس المرمى مصطفى شوبير.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ac2acf74c59b777163e932f.png', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/sport/1839889-%D8%AE%D8%B7%D8%A3-%D9%81%D8%A7%D8%AF%D8%AD-%D9%85%D9%86-%D9%85%D8%B5%D8%B7%D9%81%D9%89-%D8%B4%D9%88%D8%A8%D9%8A%D8%B1-%D9%8A%D9%85%D9%86%D8%AD-%D8%AC%D9%86%D9%88%D8%A8-%D8%A5%D9%81%D8%B1%D9%8A%D9%82%D9%8A%D8%A7-%D8%A7%D9%84%D8%AA%D9%82%D8%AF%D9%85-%D8%A3%D9%85%D8%A7%D9%85-%D9%85%D8%B5%D8%B1/', 'روسيا اليوم عربي', 'https://rtarabic.com/sport/1839889-%D8%AE%D8%B7%D8%A3-%D9%81%D8%A7%D8%AF%D8%AD-%D9%85%D9%86-%D9%85%D8%B5%D8%B7%D9%81%D9%89-%D8%B4%D9%88%D8%A8%D9%8A%D8%B1-%D9%8A%D9%85%D9%86%D8%AD-%D8%AC%D9%86%D9%88%D8%A8-%D8%A5%D9%81%D8%B1%D9%8A%D9%82%D9%8A%D8%A7-%D8%A7%D9%84%D8%AA%D9%82%D8%AF%D9%85-%D8%A3%D9%85%D8%A7%D9%85-%D9%85%D8%B5%D8%B1/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-04', '2026-10-04T00:00:00.000Z'::timestamptz, 13)
