values ('bcc77f74-3908-ecce-97ab-ec7daeeb5153', 'world_news', 'rss-d53104a2c345', '"لن تكون هناك سيناء".. سموتريتش يجدد تهديداته الحادة لمصر بعد تصريحات السيسي', 'شكك وزير المالية الإسرائيلي بتسلئيل سموتريتش في تأكيدات الرئيس المصري عبد الفتاح السيسي أن القاهرة لا تمتلك طموحات إقليمية ولا تسعى إلى الحرب مع إسرائيل، ملوحا بسيناء مرة أخرى.', '<p>شكك وزير المالية الإسرائيلي بتسلئيل سموتريتش في تأكيدات الرئيس المصري عبد الفتاح السيسي أن القاهرة لا تمتلك طموحات إقليمية ولا تسعى إلى الحرب مع إسرائيل، ملوحا بسيناء مرة أخرى.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad6785c4c59b710b55dec45.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/middle_east/1845091-%D9%84%D9%86-%D8%AA%D9%83%D9%88%D9%86-%D9%87%D9%86%D8%A7%D9%83-%D8%B3%D9%8A%D9%86%D8%A7%D8%A1-%D8%B3%D9%85%D9%88%D8%AA%D8%B1%D9%8A%D8%AA%D8%B4-%D9%8A%D8%AC%D8%AF%D8%AF-%D8%AA%D9%87%D8%AF%D9%8A%D8%AF%D8%A7%D8%AA%D9%87-%D8%A7%D9%84%D8%AD%D8%A7%D8%AF%D8%A9-%D9%84%D9%85%D8%B5%D8%B1-%D8%A8%D8%B9%D8%AF-%D8%AA%D8%B5%D8%B1%D9%8A%D8%AD%D8%A7%D8%AA-%D8%A7%D9%84%D8%B3%D9%8A%D8%B3%D9%8A/', 'روسيا اليوم عربي', 'https://rtarabic.com/middle_east/1845091-%D9%84%D9%86-%D8%AA%D9%83%D9%88%D9%86-%D9%87%D9%86%D8%A7%D9%83-%D8%B3%D9%8A%D9%86%D8%A7%D8%A1-%D8%B3%D9%85%D9%88%D8%AA%D8%B1%D9%8A%D8%AA%D8%B4-%D9%8A%D8%AC%D8%AF%D8%AF-%D8%AA%D9%87%D8%AF%D9%8A%D8%AF%D8%A7%D8%AA%D9%87-%D8%A7%D9%84%D8%AD%D8%A7%D8%AF%D8%A9-%D9%84%D9%85%D8%B5%D8%B1-%D8%A8%D8%B9%D8%AF-%D8%AA%D8%B5%D8%B1%D9%8A%D8%AD%D8%A7%D8%AA-%D8%A7%D9%84%D8%B3%D9%8A%D8%B3%D9%8A/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 60)
