values ('3c97cbee-b3f0-4285-92bf-890c57572cc0', 'world_news', 'rss-80ee2725d63e', 'ترامب: زيلينسكي لا يريد إنهاء الصراع في أوكرانيا', 'صرّح الرئيس الأمريكي دونالد ترامب، بأن فلاديمير زيلينسكي لا يريد إنهاء الصراع في أوكرانيا.', '<p>صرّح الرئيس الأمريكي دونالد ترامب، بأن فلاديمير زيلينسكي لا يريد إنهاء الصراع في أوكرانيا.</p>', 'https://cdn.img.sarabic.ae/img/07ea/0a/01/1117432708_0:0:3072:1728_2072x0_60_0_0_364fbc6af8b0855fd8f96350cd69ec23.jpg', 'الصورة من سبوتنيك عربي', 'https://sarabic.ae/20261019/%D8%AA%D8%B1%D8%A7%D9%85%D8%A8-%D8%B2%D9%8A%D9%84%D9%8A%D9%86%D8%B3%D9%83%D9%8A-%D9%84%D8%A7-%D9%8A%D8%B1%D9%8A%D8%AF-%D8%A5%D9%86%D9%87%D8%A7%D8%A1-%D8%A7%D9%84%D8%B5%D8%B1%D8%A7%D8%B9-%D9%81%D9%8A-%D8%A3%D9%88%D9%83%D8%B1%D8%A7%D9%86%D9%8A%D8%A7-1117951081.html', 'سبوتنيك عربي', 'https://sarabic.ae/20261019/%D8%AA%D8%B1%D8%A7%D9%85%D8%A8-%D8%B2%D9%8A%D9%84%D9%8A%D9%86%D8%B3%D9%83%D9%8A-%D9%84%D8%A7-%D9%8A%D8%B1%D9%8A%D8%AF-%D8%A5%D9%86%D9%87%D8%A7%D8%A1-%D8%A7%D9%84%D8%B5%D8%B1%D8%A7%D8%B9-%D9%81%D9%8A-%D8%A3%D9%88%D9%83%D8%B1%D8%A7%D9%86%D9%8A%D8%A7-1117951081.html', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 58)
