values ('64dc02fe-a1e9-8237-45e0-3334abc18023', 'world_news', 'rss-5aac887cc9d4', 'ترامب: أقدر تعامل روسيا بإنصاف مع أوكرانيا- عاجل', 'صرّح الرئيس الأمريكي دونالد ترامب، اليوم الاثنين، بأن روسيا تتصرف بإنصاف تجاه أوكرانيا، معربًا عن تقديره لذلك.', '<p>صرّح الرئيس الأمريكي دونالد ترامب، اليوم الاثنين، بأن روسيا تتصرف بإنصاف تجاه أوكرانيا، معربًا عن تقديره لذلك.</p>', 'https://cdn.img.sarabic.ae/img/07e9/0c/1b/1108627959_0:0:2665:1499_600x0_80_0_0_167374fc07b0fba2de9b55434ee31ec1.jpg', 'الصورة من سبوتنيك عربي', 'https://sarabic.ae/20261019/%D8%AA%D8%B1%D8%A7%D9%85%D8%A8-%D8%A3%D9%82%D8%AF%D8%B1-%D8%AA%D8%B9%D8%A7%D9%85%D9%84-%D8%B1%D9%88%D8%B3%D9%8A%D8%A7-%D8%A8%D8%A5%D9%86%D8%B5%D8%A7%D9%81-%D9%85%D8%B9-%D8%A3%D9%88%D9%83%D8%B1%D8%A7%D9%86%D9%8A%D8%A7--%D8%B9%D8%A7%D8%AC%D9%84-1117952062.html', 'سبوتنيك عربي', 'https://sarabic.ae/20261019/%D8%AA%D8%B1%D8%A7%D9%85%D8%A8-%D8%A3%D9%82%D8%AF%D8%B1-%D8%AA%D8%B9%D8%A7%D9%85%D9%84-%D8%B1%D9%88%D8%B3%D9%8A%D8%A7-%D8%A8%D8%A5%D9%86%D8%B5%D8%A7%D9%81-%D9%85%D8%B9-%D8%A3%D9%88%D9%83%D8%B1%D8%A7%D9%86%D9%8A%D8%A7--%D8%B9%D8%A7%D8%AC%D9%84-1117952062.html', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 56)
