values ('756f5a3e-7277-e5c5-7d09-b9109a8e9079', 'world_news', 'rss-1e5ef0d4b505', 'ترامب: مستعد للقاء بوتين وشي في الصين', 'أعلن الرئيس الأميركي دونالد ترامب، الإثنين، استعداده لعقد اجتماع ثلاثي مع نظيريه الصيني شي جينبينغ والروسي فلاديمير بوتين، مشيرا إلى إمكان عقده خلال زيارته المرتقبة إلى الصين في نوفمبر، لبحث قضية الأسلحة النووية.', '<p>أعلن الرئيس الأميركي دونالد ترامب، الإثنين، استعداده لعقد اجتماع ثلاثي مع نظيريه الصيني شي جينبينغ والروسي فلاديمير بوتين، مشيرا إلى إمكان عقده خلال زيارته المرتقبة إلى الصين في نوفمبر، لبحث قضية الأسلحة النووية.</p>', 'https://images.skynewsarabia.com/images/v1/2026/10/19/1899275/95/53/1-1899275.JPG', 'الصورة من سكاي نيوز عربية', 'https://www.skynewsarabia.com/world/1899276-%D8%AA%D8%B1%D8%A7%D9%85%D8%A8-%D9%85%D8%B3%D8%AA%D8%B9%D8%AF-%D9%84%D9%84%D9%82%D8%A7%D8%A1-%D8%A8%D9%88%D8%AA%D9%8A%D9%86-%D9%88%D8%B4%D9%8A-%D8%A7%D9%84%D8%B5%D9%8A%D9%86', 'سكاي نيوز عربية', 'https://www.skynewsarabia.com/world/1899276-%D8%AA%D8%B1%D8%A7%D9%85%D8%A8-%D9%85%D8%B3%D8%AA%D8%B9%D8%AF-%D9%84%D9%84%D9%82%D8%A7%D8%A1-%D8%A8%D9%88%D8%AA%D9%8A%D9%86-%D9%88%D8%B4%D9%8A-%D8%A7%D9%84%D8%B5%D9%8A%D9%86', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 54)
