values ('c6ff8316-673f-8aca-7015-91bb0be5c8d2', 'world_news', 'rss-78255c7fa5b9', 'مصر.. الحركة المدنية تعلن رفضها قرار السيسي بشأن تحرك الجيش لدعم السعودية', 'رفضت الحركة المدنية الديمقراطية في مصر انخراط القوات المسلحة في أي حرب إقليمية لصالح أي طرف، داعية إلى تغليب المصالح الوطنية واللجوء إلى الوساطة الدبلوماسية لاحتواء التصعيد.', '<p>رفضت الحركة المدنية الديمقراطية في مصر انخراط القوات المسلحة في أي حرب إقليمية لصالح أي طرف، داعية إلى تغليب المصالح الوطنية واللجوء إلى الوساطة الدبلوماسية لاحتواء التصعيد.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad672e9423604571308ad92.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/middle_east/1845082-%D9%85%D8%B5%D8%B1-%D8%A7%D9%84%D8%AD%D8%B1%D9%83%D8%A9-%D8%A7%D9%84%D9%85%D8%AF%D9%86%D9%8A%D8%A9-%D8%AA%D8%B9%D9%84%D9%86-%D8%B1%D9%81%D8%B6%D9%87%D8%A7-%D9%82%D8%B1%D8%A7%D8%B1-%D8%A7%D9%84%D8%B3%D9%8A%D8%B3%D9%8A-%D8%A8%D8%B4%D8%A3%D9%86-%D8%AA%D8%AD%D8%B1%D9%83-%D8%A7%D9%84%D8%AC%D9%8A%D8%B4-%D9%84%D8%AF%D8%B9%D9%85-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9/', 'روسيا اليوم عربي', 'https://rtarabic.com/middle_east/1845082-%D9%85%D8%B5%D8%B1-%D8%A7%D9%84%D8%AD%D8%B1%D9%83%D8%A9-%D8%A7%D9%84%D9%85%D8%AF%D9%86%D9%8A%D8%A9-%D8%AA%D8%B9%D9%84%D9%86-%D8%B1%D9%81%D8%B6%D9%87%D8%A7-%D9%82%D8%B1%D8%A7%D8%B1-%D8%A7%D9%84%D8%B3%D9%8A%D8%B3%D9%8A-%D8%A8%D8%B4%D8%A3%D9%86-%D8%AA%D8%AD%D8%B1%D9%83-%D8%A7%D9%84%D8%AC%D9%8A%D8%B4-%D9%84%D8%AF%D8%B9%D9%85-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 53)
