values ('09634745-c6c2-2597-c865-5fbae0391324', 'world_news', 'rss-08fd4057c2c0', 'من خيبر إلى العلا... السعودية تفتح صفحات من تاريخ الجزيرة العربية أمام علماء الآثار', 'أعلنت الهيئة الملكية السعودية لمحافظة العلا إطلاق موسم الآثار لعامي 2026–2027 في العلا وخيبر، ضمن برنامج بحثي يستهدف الكشف عن مزيد من الشواهد التي توثق تاريخ الإنسان والحضارات التي تعاقبت على شمال غرب الجزيرة العربية.', '<p>أعلنت الهيئة الملكية السعودية لمحافظة العلا إطلاق موسم الآثار لعامي 2026–2027 في العلا وخيبر، ضمن برنامج بحثي يستهدف الكشف عن مزيد من الشواهد التي توثق تاريخ الإنسان والحضارات التي تعاقبت على شمال غرب الجزيرة العربية.</p>', 'https://cdn.img.sarabic.ae/img/07ea/0a/13/1117949584_0:160:3072:1888_2072x0_60_0_0_4ecc6dbca9426bca2807f2f650e2693c.jpg', 'الصورة من سبوتنيك عربي', 'https://sarabic.ae/20261019/%D9%85%D9%86-%D8%AE%D9%8A%D8%A8%D8%B1-%D8%A5%D9%84%D9%89-%D8%A7%D9%84%D8%B9%D9%84%D8%A7-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-%D8%AA%D9%81%D8%AA%D8%AD-%D8%B5%D9%81%D8%AD%D8%A7%D8%AA-%D9%85%D9%86-%D8%AA%D8%A7%D8%B1%D9%8A%D8%AE-%D8%A7%D9%84%D8%AC%D8%B2%D9%8A%D8%B1%D8%A9-%D8%A7%D9%84%D8%B9%D8%B1%D8%A8%D9%8A%D8%A9-%D8%A3%D9%85%D8%A7%D9%85-%D8%B9%D9%84%D9%85%D8%A7%D8%A1-%D8%A7%D9%84%D8%A2%D8%AB%D8%A7%D8%B1-1117950761.html', 'سبوتنيك عربي', 'https://sarabic.ae/20261019/%D9%85%D9%86-%D8%AE%D9%8A%D8%A8%D8%B1-%D8%A5%D9%84%D9%89-%D8%A7%D9%84%D8%B9%D9%84%D8%A7-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-%D8%AA%D9%81%D8%AA%D8%AD-%D8%B5%D9%81%D8%AD%D8%A7%D8%AA-%D9%85%D9%86-%D8%AA%D8%A7%D8%B1%D9%8A%D8%AE-%D8%A7%D9%84%D8%AC%D8%B2%D9%8A%D8%B1%D8%A9-%D8%A7%D9%84%D8%B9%D8%B1%D8%A8%D9%8A%D8%A9-%D8%A3%D9%85%D8%A7%D9%85-%D8%B9%D9%84%D9%85%D8%A7%D8%A1-%D8%A7%D9%84%D8%A2%D8%AB%D8%A7%D8%B1-1117950761.html', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 52)
