values ('5d82c796-176e-f643-451c-14e663599f96', 'world_news', 'rss-1520b87cc5a5', 'ترامب يوعز بالتحقيق مع أحد مستشاريه بشبهة "استغلال النفوذ"', 'أفاد موقع أكسيوس بأن الرئيس الأمريكي دونالد ترامب أمر بإجراء تحقيق مع مستشاره ريتشارد غرينيل، وذلك على خلفية شبهات تتعلق بتورطه في استغلال النفوذ والمنصب لمنفعة شخصية.', '<p>أفاد موقع أكسيوس بأن الرئيس الأمريكي دونالد ترامب أمر بإجراء تحقيق مع مستشاره ريتشارد غرينيل، وذلك على خلفية شبهات تتعلق بتورطه في استغلال النفوذ والمنصب لمنفعة شخصية.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad671104c59b710b55dec3c.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/world/1845084-%D8%AA%D8%B1%D8%A7%D9%85%D8%A8-%D9%8A%D9%88%D8%B9%D8%B2-%D8%A8%D8%A7%D9%84%D8%AA%D8%AD%D9%82%D9%8A%D9%82-%D9%85%D8%B9-%D8%A3%D8%AD%D8%AF-%D9%85%D8%B3%D8%AA%D8%B4%D8%A7%D8%B1%D9%8A%D9%87-%D8%A8%D8%B4%D8%A8%D9%87%D8%A9-%D8%A7%D8%B3%D8%AA%D8%BA%D9%84%D8%A7%D9%84-%D8%A7%D9%84%D9%86%D9%81%D9%88%D8%B0/', 'روسيا اليوم عربي', 'https://rtarabic.com/world/1845084-%D8%AA%D8%B1%D8%A7%D9%85%D8%A8-%D9%8A%D9%88%D8%B9%D8%B2-%D8%A8%D8%A7%D9%84%D8%AA%D8%AD%D9%82%D9%8A%D9%82-%D9%85%D8%B9-%D8%A3%D8%AD%D8%AF-%D9%85%D8%B3%D8%AA%D8%B4%D8%A7%D8%B1%D9%8A%D9%87-%D8%A8%D8%B4%D8%A8%D9%87%D8%A9-%D8%A7%D8%B3%D8%AA%D8%BA%D9%84%D8%A7%D9%84-%D8%A7%D9%84%D9%86%D9%81%D9%88%D8%B0/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 51)
