values ('a65197ee-7c0e-fa88-e9b4-46f14d4b759e', 'world_news', 'rss-3220ff7df80d', 'الحرس الثوري يهدد باستهداف كابلات الإنترنت الرئيسية في قاع مضيق هرمز', 'وجه الحرس الثوري الإيراني، اليوم الاثنين، تهديدا غير مباشر بالتلميح حول كابلات الإنترنت الرئيسية التي تمر عبر قاع مضيق هرمز.', '<p>وجه الحرس الثوري الإيراني، اليوم الاثنين، تهديدا غير مباشر بالتلميح حول كابلات الإنترنت الرئيسية التي تمر عبر قاع مضيق هرمز.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad670b94c59b70fce51d66e.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/world/1845083-%D8%A7%D9%84%D8%AD%D8%B1%D8%B3-%D8%A7%D9%84%D8%AB%D9%88%D8%B1%D9%8A-%D9%8A%D9%87%D8%AF%D8%AF-%D8%A8%D8%A7%D8%B3%D8%AA%D9%87%D8%AF%D8%A7%D9%81-%D9%83%D8%A7%D8%A8%D9%84%D8%A7%D8%AA-%D8%A7%D9%84%D8%A5%D9%86%D8%AA%D8%B1%D9%86%D8%AA-%D8%A7%D9%84%D8%B1%D8%A6%D9%8A%D8%B3%D9%8A%D8%A9-%D9%81%D9%8A-%D9%82%D8%A7%D8%B9-%D9%85%D8%B6%D9%8A%D9%82-%D9%87%D8%B1%D9%85%D8%B2/', 'روسيا اليوم عربي', 'https://rtarabic.com/world/1845083-%D8%A7%D9%84%D8%AD%D8%B1%D8%B3-%D8%A7%D9%84%D8%AB%D9%88%D8%B1%D9%8A-%D9%8A%D9%87%D8%AF%D8%AF-%D8%A8%D8%A7%D8%B3%D8%AA%D9%87%D8%AF%D8%A7%D9%81-%D9%83%D8%A7%D8%A8%D9%84%D8%A7%D8%AA-%D8%A7%D9%84%D8%A5%D9%86%D8%AA%D8%B1%D9%86%D8%AA-%D8%A7%D9%84%D8%B1%D8%A6%D9%8A%D8%B3%D9%8A%D8%A9-%D9%81%D9%8A-%D9%82%D8%A7%D8%B9-%D9%85%D8%B6%D9%8A%D9%82-%D9%87%D8%B1%D9%85%D8%B2/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 50)
