values ('e835c735-b04b-8101-54b1-362287262a10', 'world_news', 'rss-432edfeedd31', 'ترامب: زيلينسكي لا يريد إنهاء الصراع في أوكرانيا', 'قال الرئيس الأمريكي دونالد ترامب إن زيلينسكي لا يسهم في إنهاء الصراع، مؤكدا أنه قد حان الوقت للبحث عن طرف آخر للتفاوض من أجل التسوية في أوكرانيا.', '<p>قال الرئيس الأمريكي دونالد ترامب إن زيلينسكي لا يسهم في إنهاء الصراع، مؤكدا أنه قد حان الوقت للبحث عن طرف آخر للتفاوض من أجل التسوية في أوكرانيا.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad675c2423604555471477b.png', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/world/1845081-%D8%AA%D8%B1%D8%A7%D9%85%D8%A8-%D8%B2%D9%8A%D9%84%D9%8A%D9%86%D8%B3%D9%83%D9%8A-%D9%84%D8%A7-%D9%8A%D8%B1%D9%8A%D8%AF-%D8%A5%D9%86%D9%87%D8%A7%D8%A1-%D8%A7%D9%84%D8%B5%D8%B1%D8%A7%D8%B9-%D9%81%D9%8A-%D8%A3%D9%88%D9%83%D8%B1%D8%A7%D9%86%D9%8A%D8%A7/', 'روسيا اليوم عربي', 'https://rtarabic.com/world/1845081-%D8%AA%D8%B1%D8%A7%D9%85%D8%A8-%D8%B2%D9%8A%D9%84%D9%8A%D9%86%D8%B3%D9%83%D9%8A-%D9%84%D8%A7-%D9%8A%D8%B1%D9%8A%D8%AF-%D8%A5%D9%86%D9%87%D8%A7%D8%A1-%D8%A7%D9%84%D8%B5%D8%B1%D8%A7%D8%B9-%D9%81%D9%8A-%D8%A3%D9%88%D9%83%D8%B1%D8%A7%D9%86%D9%8A%D8%A7/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 48)
