values ('4863b544-2c18-f0e9-ceed-fbe4087a46ed', 'world_news', 'rss-96acd9afd9a1', 'محمد بن زايد وماكرون يبحثان التعاون والتطورات الإقليمية', 'بحث الشيخ محمد بن زايد آل نهيان، رئيس دولة الإمارات، والرئيس الفرنسي إيمانويل ماكرون، الإثنين، مسار العلاقات الاستراتيجية التي تجمع البلدين وسبل توسيع آفاقها، خاصة في المجالات الاقتصادية والاستثمارية والطاقة والتكنولوجيا المتقدمة والذكاء ا', '<p>بحث الشيخ محمد بن زايد آل نهيان، رئيس دولة الإمارات، والرئيس الفرنسي إيمانويل ماكرون، الإثنين، مسار العلاقات الاستراتيجية التي تجمع البلدين وسبل توسيع آفاقها، خاصة في المجالات الاقتصادية والاستثمارية والطاقة والتكنولوجيا المتقدمة والذكاء الاصطناعي، وغيرها من الجوانب التي تخدم رؤية البلدين وتطلعاتهما نحو تحقيق التنمية المستدامة والازدهار لشعبيهما.</p>', 'https://images.skynewsarabia.com/images/v1/2026/10/19/1899261/95/53/1-1899261.jpeg', 'الصورة من سكاي نيوز عربية', 'https://www.skynewsarabia.com/middle-east/1899263-%D9%85%D8%AD%D9%85%D8%AF-%D8%A8%D9%86-%D8%B2%D8%A7%D9%8A%D8%AF-%D9%88%D9%85%D8%A7%D9%83%D8%B1%D9%88%D9%86-%D9%8A%D8%A8%D8%AD%D8%AB%D8%A7%D9%86-%D8%A7%D9%84%D8%AA%D8%B9%D8%A7%D9%88%D9%86-%D9%88%D8%A7%D9%84%D8%AA%D8%B7%D9%88%D8%B1%D8%A7%D8%AA-%D8%A7%D9%84%D8%A5%D9%82%D9%84%D9%8A%D9%85%D9%8A%D8%A9', 'سكاي نيوز عربية', 'https://www.skynewsarabia.com/middle-east/1899263-%D9%85%D8%AD%D9%85%D8%AF-%D8%A8%D9%86-%D8%B2%D8%A7%D9%8A%D8%AF-%D9%88%D9%85%D8%A7%D9%83%D8%B1%D9%88%D9%86-%D9%8A%D8%A8%D8%AD%D8%AB%D8%A7%D9%86-%D8%A7%D9%84%D8%AA%D8%B9%D8%A7%D9%88%D9%86-%D9%88%D8%A7%D9%84%D8%AA%D8%B7%D9%88%D8%B1%D8%A7%D8%AA-%D8%A7%D9%84%D8%A5%D9%82%D9%84%D9%8A%D9%85%D9%8A%D8%A9', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 47)
