values ('552fec64-325d-8084-7037-0c7c80953025', 'world_news', 'rss-f4970d4ca40f', 'سلوتسكي: الاحتجاجات في فرنسا تعكس الفشل التام لسياسة ماكرون وقد تنقلب لفوضى عارمة', 'قال ليونيد سلوتسكي، عضو لجنة الشؤون الدولية بمجلس الدوما، إن الاحتجاجات في فرنسا التي تنقلب إلى فوضى عارمة واضطرابات في الشوارع، تمثل فشلا تاما لسياسة رئيسها إيمانويل ماكرون.', '<p>قال ليونيد سلوتسكي، عضو لجنة الشؤون الدولية بمجلس الدوما، إن الاحتجاجات في فرنسا التي تنقلب إلى فوضى عارمة واضطرابات في الشوارع، تمثل فشلا تاما لسياسة رئيسها إيمانويل ماكرون.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad66ce342360455c44ca76d.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/world/1845077-%D8%B3%D9%84%D9%88%D8%AA%D8%B3%D9%83%D9%8A-%D8%A7%D9%84%D8%A7%D8%AD%D8%AA%D8%AC%D8%A7%D8%AC%D8%A7%D8%AA-%D9%81%D9%8A-%D9%81%D8%B1%D9%86%D8%B3%D8%A7-%D8%AA%D8%B9%D9%83%D8%B3-%D8%A7%D9%84%D9%81%D8%B4%D9%84-%D8%A7%D9%84%D8%AA%D8%A7%D9%85-%D9%84%D8%B3%D9%8A%D8%A7%D8%B3%D8%A9-%D9%85%D8%A7%D9%83%D8%B1%D9%88%D9%86-%D9%88%D9%82%D8%AF-%D8%AA%D9%86%D9%82%D9%84%D8%A8-%D9%84%D9%81%D9%88%D8%B6%D9%89-%D8%B9%D8%A7%D8%B1%D9%85%D8%A9/', 'روسيا اليوم عربي', 'https://rtarabic.com/world/1845077-%D8%B3%D9%84%D9%88%D8%AA%D8%B3%D9%83%D9%8A-%D8%A7%D9%84%D8%A7%D8%AD%D8%AA%D8%AC%D8%A7%D8%AC%D8%A7%D8%AA-%D9%81%D9%8A-%D9%81%D8%B1%D9%86%D8%B3%D8%A7-%D8%AA%D8%B9%D9%83%D8%B3-%D8%A7%D9%84%D9%81%D8%B4%D9%84-%D8%A7%D9%84%D8%AA%D8%A7%D9%85-%D9%84%D8%B3%D9%8A%D8%A7%D8%B3%D8%A9-%D9%85%D8%A7%D9%83%D8%B1%D9%88%D9%86-%D9%88%D9%82%D8%AF-%D8%AA%D9%86%D9%82%D9%84%D8%A8-%D9%84%D9%81%D9%88%D8%B6%D9%89-%D8%B9%D8%A7%D8%B1%D9%85%D8%A9/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 46)
