values ('ce856bab-bbd3-0b15-91ae-926764dd6e91', 'world_news', 'rss-8119ed417bc9', 'الخارجية الإيرانية تستدعي السفير الألماني لدى طهران', 'استدعت الخارجية الإيرانية سفير ألمانيا لدى طهران أكسل ديتمان لتقديم احتجاج بسبب اتهامات بعض المسؤولين الألمان لإيران.', '<p>استدعت الخارجية الإيرانية سفير ألمانيا لدى طهران أكسل ديتمان لتقديم احتجاج بسبب اتهامات بعض المسؤولين الألمان لإيران.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad66e534c59b710020e6c22.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/world/1845075-%D8%A5%D9%8A%D8%B1%D8%A7%D9%86-%D8%AA%D8%B3%D8%AA%D8%AF%D8%B9%D9%8A-%D8%A7%D9%84%D8%B3%D9%81%D9%8A%D8%B1-%D8%A7%D9%84%D8%A3%D9%84%D9%85%D8%A7%D9%86%D9%8A-%D9%84%D8%AF%D9%89-%D8%B7%D9%87%D8%B1%D8%A7%D9%86/', 'روسيا اليوم عربي', 'https://rtarabic.com/world/1845075-%D8%A5%D9%8A%D8%B1%D8%A7%D9%86-%D8%AA%D8%B3%D8%AA%D8%AF%D8%B9%D9%8A-%D8%A7%D9%84%D8%B3%D9%81%D9%8A%D8%B1-%D8%A7%D9%84%D8%A3%D9%84%D9%85%D8%A7%D9%86%D9%8A-%D9%84%D8%AF%D9%89-%D8%B7%D9%87%D8%B1%D8%A7%D9%86/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 43)
