values ('47d301f7-fb3e-a75d-d9c4-f99c3d47020f', 'world_news', 'rss-e6904b556086', 'بينهم 190 طفلا.. إدانة زعيم طائفة "يوم القيامة" في كينيا بقتل 400 من أتباعه "جوعا"', 'أدانت محكمة كينية زعيم طائفة "يوم القيامة" بول ماكنزي، المتسبب في وفاة أكثر من 400 من أتباعه، وقتل 190 طفلا وشخص بالغ، في واحدة من أخطر قضايا التطرف الديني في البلاد.', '<p>أدانت محكمة كينية زعيم طائفة "يوم القيامة" بول ماكنزي، المتسبب في وفاة أكثر من 400 من أتباعه، وقتل 190 طفلا وشخص بالغ، في واحدة من أخطر قضايا التطرف الديني في البلاد.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad6671242360459e6053e86.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/world/1845070-%D8%A8%D9%8A%D9%86%D9%87%D9%85-190-%D8%B7%D9%81%D9%84%D8%A7-%D8%A5%D8%AF%D8%A7%D9%86%D8%A9-%D8%B2%D8%B9%D9%8A%D9%85-%D8%B7%D8%A7%D8%A6%D9%81%D8%A9-%D9%8A%D9%88%D9%85-%D8%A7%D9%84%D9%82%D9%8A%D8%A7%D9%85%D8%A9-%D9%81%D9%8A-%D9%83%D9%8A%D9%86%D9%8A%D8%A7-%D8%A8%D9%82%D8%AA%D9%84-400-%D9%85%D9%86-%D8%A3%D8%AA%D8%A8%D8%A7%D8%B9%D9%87-%D8%AC%D9%88%D8%B9%D8%A7/', 'روسيا اليوم عربي', 'https://rtarabic.com/world/1845070-%D8%A8%D9%8A%D9%86%D9%87%D9%85-190-%D8%B7%D9%81%D9%84%D8%A7-%D8%A5%D8%AF%D8%A7%D9%86%D8%A9-%D8%B2%D8%B9%D9%8A%D9%85-%D8%B7%D8%A7%D8%A6%D9%81%D8%A9-%D9%8A%D9%88%D9%85-%D8%A7%D9%84%D9%82%D9%8A%D8%A7%D9%85%D8%A9-%D9%81%D9%8A-%D9%83%D9%8A%D9%86%D9%8A%D8%A7-%D8%A8%D9%82%D8%AA%D9%84-400-%D9%85%D9%86-%D8%A3%D8%AA%D8%A8%D8%A7%D8%B9%D9%87-%D8%AC%D9%88%D8%B9%D8%A7/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 42)
