values ('ac3a149e-cefe-c10d-7b91-00daa34c4e32', 'world_news', 'rss-20b67a1a12b4', 'ملفات وتحديات أمام حكومة المنصوري في المغرب... ما التفاصيل؟', 'تواجه الحكومة المغربية الجديدة، برئاسة فاطمة الزهراء المنصوري، جملة من الملفات الاجتماعية والاقتصادية والسياسية، في مقدمتها محاربة البطالة والفقر، وحماية القدرة الشرائية، وتحسين أداء قطاعات الصحة والتعليم، إلى جانب تعزيز الحماية الاجتماعية.', '<p>تواجه الحكومة المغربية الجديدة، برئاسة فاطمة الزهراء المنصوري، جملة من الملفات الاجتماعية والاقتصادية والسياسية، في مقدمتها محاربة البطالة والفقر، وحماية القدرة الشرائية، وتحسين أداء قطاعات الصحة والتعليم، إلى جانب تعزيز الحماية الاجتماعية.</p>', 'https://cdn.img.sarabic.ae/img/07ea/09/1d/1117381790_0:160:3072:1888_2072x0_60_0_0_fb431588bcceb9ddce9f9dd73ce4fef5.jpg', 'الصورة من سبوتنيك عربي', 'https://sarabic.ae/20261019/%D9%85%D9%84%D9%81%D8%A7%D8%AA-%D9%88%D8%AA%D8%AD%D8%AF%D9%8A%D8%A7%D8%AA-%D8%A3%D9%85%D8%A7%D9%85-%D8%AD%D9%83%D9%88%D9%85%D8%A9-%D8%A7%D9%84%D9%85%D9%86%D8%B5%D9%88%D8%B1%D9%8A-%D9%81%D9%8A-%D8%A7%D9%84%D9%85%D8%BA%D8%B1%D8%A8-%D9%85%D8%A7-%D8%A7%D9%84%D8%AA%D9%81%D8%A7%D8%B5%D9%8A%D9%84-1117949149.html', 'سبوتنيك عربي', 'https://sarabic.ae/20261019/%D9%85%D9%84%D9%81%D8%A7%D8%AA-%D9%88%D8%AA%D8%AD%D8%AF%D9%8A%D8%A7%D8%AA-%D8%A3%D9%85%D8%A7%D9%85-%D8%AD%D9%83%D9%88%D9%85%D8%A9-%D8%A7%D9%84%D9%85%D9%86%D8%B5%D9%88%D8%B1%D9%8A-%D9%81%D9%8A-%D8%A7%D9%84%D9%85%D8%BA%D8%B1%D8%A8-%D9%85%D8%A7-%D8%A7%D9%84%D8%AA%D9%81%D8%A7%D8%B5%D9%8A%D9%84-1117949149.html', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 40)
