values ('ffa3743a-7404-4d32-3819-67c075d7cc2f', 'world_news', 'rss-abfbaa39d6db', 'التحالف يوجه تحذيرا شديد اللهجة للحوثيين على خلفية عمليات تهريب الأسلحة والصواريخ', 'وجه تحالف دعم الشرعية في اليمن في بيان له اليوم الاثنين، تحذيرا شديد اللهجة للحوثيين على خلفية عمليات تهريب الأسلحة والصواريخ.', '<p>وجه تحالف دعم الشرعية في اليمن في بيان له اليوم الاثنين، تحذيرا شديد اللهجة للحوثيين على خلفية عمليات تهريب الأسلحة والصواريخ.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad66a7b42360459e6053e90.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/middle_east/1845073-%D8%A7%D9%84%D8%AA%D8%AD%D8%A7%D9%84%D9%81-%D9%8A%D9%88%D8%AC%D9%87-%D8%AA%D8%AD%D8%B0%D9%8A%D8%B1%D8%A7-%D8%B4%D8%AF%D9%8A%D8%AF-%D8%A7%D9%84%D9%84%D9%87%D8%AC%D8%A9-%D9%84%D9%84%D8%AD%D9%88%D8%AB%D9%8A%D9%8A%D9%86-%D8%B9%D9%84%D9%89-%D8%AE%D9%84%D9%81%D9%8A%D8%A9-%D8%B9%D9%85%D9%84%D9%8A%D8%A7%D8%AA-%D8%AA%D9%87%D8%B1%D9%8A%D8%A8-%D8%A7%D9%84%D8%A3%D8%B3%D9%84%D8%AD%D8%A9-%D9%88%D8%A7%D9%84%D8%B5%D9%88%D8%A7%D8%B1%D9%8A%D8%AE/', 'روسيا اليوم عربي', 'https://rtarabic.com/middle_east/1845073-%D8%A7%D9%84%D8%AA%D8%AD%D8%A7%D9%84%D9%81-%D9%8A%D9%88%D8%AC%D9%87-%D8%AA%D8%AD%D8%B0%D9%8A%D8%B1%D8%A7-%D8%B4%D8%AF%D9%8A%D8%AF-%D8%A7%D9%84%D9%84%D9%87%D8%AC%D8%A9-%D9%84%D9%84%D8%AD%D9%88%D8%AB%D9%8A%D9%8A%D9%86-%D8%B9%D9%84%D9%89-%D8%AE%D9%84%D9%81%D9%8A%D8%A9-%D8%B9%D9%85%D9%84%D9%8A%D8%A7%D8%AA-%D8%AA%D9%87%D8%B1%D9%8A%D8%A8-%D8%A7%D9%84%D8%A3%D8%B3%D9%84%D8%AD%D8%A9-%D9%88%D8%A7%D9%84%D8%B5%D9%88%D8%A7%D8%B1%D9%8A%D8%AE/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 39)
