values ('bcd8ffa3-4196-adc7-dd08-eeca4d73e2b8', 'world_news', 'rss-f73d0286b9fa', 'فيديو.. مسيّرة تحمل جنديا أوكرانيا مصابا وتطير به', 'في مهمة وصفت بأنها الأولى من نوعها، نجحت طائرة مسيّرة في إجلاء جندي أوكراني مصاب، من جبهة القتال مع القوات الروسية إلى منطقة آمنة.', '<p>في مهمة وصفت بأنها الأولى من نوعها، نجحت طائرة مسيّرة في إجلاء جندي أوكراني مصاب، من جبهة القتال مع القوات الروسية إلى منطقة آمنة.</p>', 'https://images.skynewsarabia.com/images/v1/2026/10/19/1899266/95/53/1-1899266.jpeg', 'الصورة من سكاي نيوز عربية', 'https://www.skynewsarabia.com/world/1899270-%D9%81%D9%8A%D8%AF%D9%8A%D9%88-%D9%85%D8%B3%D9%8A%D8%B1%D8%A9-%D8%AA%D8%AD%D9%85%D9%84-%D8%AC%D9%86%D8%AF%D9%8A%D8%A7-%D8%A3%D9%88%D9%83%D8%B1%D8%A7%D9%86%D9%8A%D8%A7-%D9%85%D8%B5%D8%A7%D8%A8%D8%A7-%D9%88%D8%AA%D8%B7%D9%8A%D8%B1', 'سكاي نيوز عربية', 'https://www.skynewsarabia.com/world/1899270-%D9%81%D9%8A%D8%AF%D9%8A%D9%88-%D9%85%D8%B3%D9%8A%D8%B1%D8%A9-%D8%AA%D8%AD%D9%85%D9%84-%D8%AC%D9%86%D8%AF%D9%8A%D8%A7-%D8%A3%D9%88%D9%83%D8%B1%D8%A7%D9%86%D9%8A%D8%A7-%D9%85%D8%B5%D8%A7%D8%A8%D8%A7-%D9%88%D8%AA%D8%B7%D9%8A%D8%B1', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 38)
