values ('8ef72d61-ed08-2871-2136-3a57fa0f07d7', 'world_news', 'rss-03a98374e73c', 'قبل انتهاء الحماية.. واشنطن تمهل السودانيين والأوكرانيين', 'أعلنت وزارة الأمن الداخلي الأميركية، الإثنين، استمرار وضع الحماية المؤقتة للمشمولين به من السودان وأوكرانيا في الوقت الحالي، بعدما كان من المقرر انتهاء سريانه يوم الاثنين.', '<p>أعلنت وزارة الأمن الداخلي الأميركية، الإثنين، استمرار وضع الحماية المؤقتة للمشمولين به من السودان وأوكرانيا في الوقت الحالي، بعدما كان من المقرر انتهاء سريانه يوم الاثنين.</p>', 'https://images.skynewsarabia.com/images/v1/2026/10/19/1899264/95/53/1-1899264.jpg', 'الصورة من سكاي نيوز عربية', 'https://www.skynewsarabia.com/world/1899267-%D8%A7%D9%86%D8%AA%D9%87%D8%A7%D8%A1-%D8%A7%D9%84%D8%AD%D9%85%D8%A7%D9%8A%D8%A9-%D9%88%D8%A7%D8%B4%D9%86%D8%B7%D9%86-%D8%AA%D9%85%D9%87%D9%84-%D8%A7%D9%84%D8%B3%D9%88%D8%AF%D8%A7%D9%86%D9%8A%D9%8A%D9%86-%D9%88%D8%A7%D9%84%D8%A3%D9%88%D9%83%D8%B1%D8%A7%D9%86%D9%8A%D9%8A%D9%86', 'سكاي نيوز عربية', 'https://www.skynewsarabia.com/world/1899267-%D8%A7%D9%86%D8%AA%D9%87%D8%A7%D8%A1-%D8%A7%D9%84%D8%AD%D9%85%D8%A7%D9%8A%D8%A9-%D9%88%D8%A7%D8%B4%D9%86%D8%B7%D9%86-%D8%AA%D9%85%D9%87%D9%84-%D8%A7%D9%84%D8%B3%D9%88%D8%AF%D8%A7%D9%86%D9%8A%D9%8A%D9%86-%D9%88%D8%A7%D9%84%D8%A3%D9%88%D9%83%D8%B1%D8%A7%D9%86%D9%8A%D9%8A%D9%86', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 35)
