values ('0271f4c2-f15f-e230-20fe-d1424eaec05e', 'world_news', 'rss-43ffeca9c8b7', 'تغطية خاصة لأعمال الشغب والعنف التي شهدتها الاحتجاجات قي فرنسا', 'في هذا العدد الخاص نعود على يوم السابع عشر من أكتوبر في فرنسا والذي شهد مظاهرات في عدة مدن ضد غلاء المعيشة والمطالبة بتحسين ظروف التعليم في الثانويات، مظاهرات تخللتها أعمال عنف وشغب ونهب جعلت مظاهر الخراب طاغية على عدد من المدن الفرنسية عل', '<p>في هذا العدد الخاص نعود على يوم السابع عشر من أكتوبر في فرنسا والذي شهد مظاهرات في عدة مدن ضد غلاء المعيشة والمطالبة بتحسين ظروف التعليم في الثانويات، مظاهرات تخللتها أعمال عنف وشغب ونهب جعلت مظاهر الخراب طاغية على عدد من المدن الفرنسية على رأسها باريس ومارسيليا.</p>', 'https://s.france24.com/media/display/136366f8-cbed-11f1-b471-6313a763b466/w:1024/p:16x9/Arabe-2026-10-19T17-10-54-934Z.jpg', 'الصورة من فرانس 24', 'https://www.france24.com/ar/%D8%A8%D8%B1%D8%A7%D9%85%D8%AC/%D8%A7%D9%84%D9%86%D9%82%D8%A7%D8%B4/20261019-%D8%AA%D8%BA%D8%B7%D9%8A%D8%A9-%D8%AE%D8%A7%D8%B5%D8%A9-%D9%84%D8%A3%D8%B9%D9%85%D8%A7%D9%84-%D8%A7%D9%84%D8%B4%D8%BA%D8%A8-%D9%88%D8%A7%D9%84%D8%B9%D9%86%D9%81-%D8%A7%D9%84%D8%AA%D9%8A-%D8%B4%D9%87%D8%AF%D8%AA%D9%87%D8%A7-%D8%A7%D9%84%D8%A7%D8%AD%D8%AA%D8%AC%D8%A7%D8%AC%D8%A7%D8%AA-%D9%82%D9%8A-%D9%81%D8%B1%D9%86%D8%B3%D8%A7', 'فرانس 24', 'https://www.france24.com/ar/%D8%A8%D8%B1%D8%A7%D9%85%D8%AC/%D8%A7%D9%84%D9%86%D9%82%D8%A7%D8%B4/20261019-%D8%AA%D8%BA%D8%B7%D9%8A%D8%A9-%D8%AE%D8%A7%D8%B5%D8%A9-%D9%84%D8%A3%D8%B9%D9%85%D8%A7%D9%84-%D8%A7%D9%84%D8%B4%D8%BA%D8%A8-%D9%88%D8%A7%D9%84%D8%B9%D9%86%D9%81-%D8%A7%D9%84%D8%AA%D9%8A-%D8%B4%D9%87%D8%AF%D8%AA%D9%87%D8%A7-%D8%A7%D9%84%D8%A7%D8%AD%D8%AA%D8%AC%D8%A7%D8%AC%D8%A7%D8%AA-%D9%82%D9%8A-%D9%81%D8%B1%D9%86%D8%B3%D8%A7', '["النقاش"]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 34)
