values ('fdbec2bf-62d2-1025-90bc-70133bb15ed9', 'world_news', 'rss-58f3cd4dc5a5', 'فرنسا: حظر تجول جزئي على خلفية "فوضى" شهدتها عطلة نهاية الأسبوع', 'عقب الانتهاء من اجتماع طارئ مع عدد من وزرائه أعلن رئيس الحكومة سيباستيان لوكورنو يوم الإثنين 19 أكتوبر عن سلسلة من التدابير في أعقاب المظاهرات التي شهدتها عطلة نهاية الأسبوع. تضررت أكثر من 3000 منشأة تجارية جراء أعمال العنف والنهب تعتزم ال', '<p>عقب الانتهاء من اجتماع طارئ مع عدد من وزرائه أعلن رئيس الحكومة سيباستيان لوكورنو يوم الإثنين 19 أكتوبر عن سلسلة من التدابير في أعقاب المظاهرات التي شهدتها عطلة نهاية الأسبوع. تضررت أكثر من 3000 منشأة تجارية جراء أعمال العنف والنهب تعتزم الحكومة إقامة "صندوق دعم" لمساعدة المتضررين بالإضافة إلى اللجوء لتدابير "البطالة الجزئية" ولم يستبعد لوكورنو إعلان حالة الطوارئ "إذا لزم الأمر". وزارة الداخلية أعلنت أن أعداد الموقوفين في الساعات الأولى لأعمال العنف وصلت إلى نحو 2400 شخص.</p>', 'https://s.france24.com/media/display/0870fa3e-cbe9-11f1-a113-2d1c143cdef3/w:1024/p:16x9/miniature-lecornu.jpg', 'الصورة من فرانس 24', 'https://www.france24.com/ar/%D9%81%D9%8A%D8%AF%D9%8A%D9%88/20261019-%D9%81%D8%B1%D9%86%D8%B3%D8%A7-%D8%AD%D8%B8%D8%B1-%D8%AA%D8%AC%D9%88%D9%84-%D8%AC%D8%B2%D8%A6%D9%8A-%D8%B9%D9%84%D9%89-%D8%AE%D9%84%D9%81%D9%8A%D8%A9-%D9%81%D9%88%D8%B6%D9%89-%D8%B4%D9%87%D8%AF%D8%AA%D9%87%D8%A7-%D8%B9%D8%B7%D9%84%D8%A9-%D9%86%D9%87%D8%A7%D9%8A%D8%A9-%D8%A7%D9%84%D8%A3%D8%B3%D8%A8%D9%88%D8%B9', 'فرانس 24', 'https://www.france24.com/ar/%D9%81%D9%8A%D8%AF%D9%8A%D9%88/20261019-%D9%81%D8%B1%D9%86%D8%B3%D8%A7-%D8%AD%D8%B8%D8%B1-%D8%AA%D8%AC%D9%88%D9%84-%D8%AC%D8%B2%D8%A6%D9%8A-%D8%B9%D9%84%D9%89-%D8%AE%D9%84%D9%81%D9%8A%D8%A9-%D9%81%D9%88%D8%B6%D9%89-%D8%B4%D9%87%D8%AF%D8%AA%D9%87%D8%A7-%D8%B9%D8%B7%D9%84%D8%A9-%D9%86%D9%87%D8%A7%D9%8A%D8%A9-%D8%A7%D9%84%D8%A3%D8%B3%D8%A8%D9%88%D8%B9', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 30)
