values ('9488615c-d13c-2606-c394-fca551c0503c', 'world_news', 'rss-ac56fc9fa111', 'اليمن.. معارك في كهبوب وصواريخ بالستية حوثية على مأرب', 'أعلنت ألوية العمالقة الجنوبية، الإثنين، تكبيد الحوثيين مئات القتلى والجرحى، وإجبارهم على التراجع في جبهة كهبوب جنوب غربي اليمن، عقب هجوم شنته الجماعة على مواقع القوات.', '<p>أعلنت ألوية العمالقة الجنوبية، الإثنين، تكبيد الحوثيين مئات القتلى والجرحى، وإجبارهم على التراجع في جبهة كهبوب جنوب غربي اليمن، عقب هجوم شنته الجماعة على مواقع القوات.</p>', 'https://images.skynewsarabia.com/images/v1/2026/10/17/1898822/95/53/1-1898822.jpg', 'الصورة من سكاي نيوز عربية', 'https://www.skynewsarabia.com/middle-east/1899256-%D8%A7%D9%84%D9%8A%D9%85%D9%86-%D9%85%D8%B9%D8%A7%D8%B1%D9%83-%D9%83%D9%87%D8%A8%D9%88%D8%A8-%D9%88%D8%B5%D9%88%D8%A7%D8%B1%D9%8A%D8%AE-%D8%A8%D8%A7%D9%84%D8%B3%D8%AA%D9%8A%D8%A9-%D8%AD%D9%88%D8%AB%D9%8A%D8%A9-%D9%85%D8%A3%D8%B1%D8%A8', 'سكاي نيوز عربية', 'https://www.skynewsarabia.com/middle-east/1899256-%D8%A7%D9%84%D9%8A%D9%85%D9%86-%D9%85%D8%B9%D8%A7%D8%B1%D9%83-%D9%83%D9%87%D8%A8%D9%88%D8%A8-%D9%88%D8%B5%D9%88%D8%A7%D8%B1%D9%8A%D8%AE-%D8%A8%D8%A7%D9%84%D8%B3%D8%AA%D9%8A%D8%A9-%D8%AD%D9%88%D8%AB%D9%8A%D8%A9-%D9%85%D8%A3%D8%B1%D8%A8', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 29)
