values ('db31d893-a45e-7c85-86d5-4c841be479f0', 'world_news', 'rss-3b42c22acb9c', 'الرئيس الجزائري يبحث حماية القدرة الشرائية... إجراءات جديدة لضبط الأسعار وتموين السوق', 'ترأس الرئيس الجزائري عبد المجيد تبون، اجتماعًا لمجلس الوزراء، خُصص من بين ملفات أخرى، لبحث آليات المتابعة اليومية لأسعار المواد الاستهلاكية الأساسية، وضمان وفرتها عبر مختلف ولايات الوطن في إطار الجهود الرامية إلى حماية القدرة الشرائية للمو', '<p>ترأس الرئيس الجزائري عبد المجيد تبون، اجتماعًا لمجلس الوزراء، خُصص من بين ملفات أخرى، لبحث آليات المتابعة اليومية لأسعار المواد الاستهلاكية الأساسية، وضمان وفرتها عبر مختلف ولايات الوطن في إطار الجهود الرامية إلى حماية القدرة الشرائية للمواطنين.</p>', 'https://cdn.img.sarabic.ae/img/07ea/07/11/1115291658_0:67:1280:787_600x0_80_0_0_c30f1a263f5386f2ed69eb9b42bd4a68.jpg', 'الصورة من سبوتنيك عربي', 'https://sarabic.ae/20261019/%D8%A7%D9%84%D8%B1%D8%A6%D9%8A%D8%B3-%D8%A7%D9%84%D8%AC%D8%B2%D8%A7%D8%A6%D8%B1%D9%8A-%D9%8A%D8%A8%D8%AD%D8%AB-%D8%AD%D9%85%D8%A7%D9%8A%D8%A9-%D8%A7%D9%84%D9%82%D8%AF%D8%B1%D8%A9-%D8%A7%D9%84%D8%B4%D8%B1%D8%A7%D8%A6%D9%8A%D8%A9-%D8%A5%D8%AC%D8%B1%D8%A7%D8%A1%D8%A7%D8%AA-%D8%AC%D8%AF%D9%8A%D8%AF%D8%A9-%D9%84%D8%B6%D8%A8%D8%B7-%D8%A7%D9%84%D8%A3%D8%B3%D8%B9%D8%A7%D8%B1-%D9%88%D8%AA%D9%85%D9%88%D9%8A%D9%86-%D8%A7%D9%84%D8%B3%D9%88%D9%82-1117947922.html', 'سبوتنيك عربي', 'https://sarabic.ae/20261019/%D8%A7%D9%84%D8%B1%D8%A6%D9%8A%D8%B3-%D8%A7%D9%84%D8%AC%D8%B2%D8%A7%D8%A6%D8%B1%D9%8A-%D9%8A%D8%A8%D8%AD%D8%AB-%D8%AD%D9%85%D8%A7%D9%8A%D8%A9-%D8%A7%D9%84%D9%82%D8%AF%D8%B1%D8%A9-%D8%A7%D9%84%D8%B4%D8%B1%D8%A7%D8%A6%D9%8A%D8%A9-%D8%A5%D8%AC%D8%B1%D8%A7%D8%A1%D8%A7%D8%AA-%D8%AC%D8%AF%D9%8A%D8%AF%D8%A9-%D9%84%D8%B6%D8%A8%D8%B7-%D8%A7%D9%84%D8%A3%D8%B3%D8%B9%D8%A7%D8%B1-%D9%88%D8%AA%D9%85%D9%88%D9%8A%D9%86-%D8%A7%D9%84%D8%B3%D9%88%D9%82-1117947922.html', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 27)
