values ('a42d9710-27e8-91ec-d0fd-2c4b837ac507', 'world_news', 'rss-15d2090f3827', 'بعد أعمال الشغب.. حظر تجول بمدن في شمال فرنسا', 'أعلن رئيس الحكومة الفرنسية سيباستيان لوكورنو، الإثنين، فرض حظر تجول جزئي في 4 مدن شمالي البلاد، ليلتي الإثنين والثلاثاء، عقب أعمال الشغب والعنف التي رافقت الاحتجاجات ضد غلاء المعيشة.', '<p>أعلن رئيس الحكومة الفرنسية سيباستيان لوكورنو، الإثنين، فرض حظر تجول جزئي في 4 مدن شمالي البلاد، ليلتي الإثنين والثلاثاء، عقب أعمال الشغب والعنف التي رافقت الاحتجاجات ضد غلاء المعيشة.</p>', 'https://images.skynewsarabia.com/images/v1/2026/10/19/1899247/95/53/1-1899247.jpg', 'الصورة من سكاي نيوز عربية', 'https://www.skynewsarabia.com/world/1899249-%D8%A3%D8%B9%D9%85%D8%A7%D9%84-%D8%A7%D9%84%D8%B4%D8%BA%D8%A8-%D8%AD%D8%B8%D8%B1-%D8%AA%D8%AC%D9%88%D9%84-%D8%A8%D9%85%D8%AF%D9%86-%D8%B4%D9%85%D8%A7%D9%84-%D9%81%D8%B1%D9%86%D8%B3%D8%A7', 'سكاي نيوز عربية', 'https://www.skynewsarabia.com/world/1899249-%D8%A3%D8%B9%D9%85%D8%A7%D9%84-%D8%A7%D9%84%D8%B4%D8%BA%D8%A8-%D8%AD%D8%B8%D8%B1-%D8%AA%D8%AC%D9%88%D9%84-%D8%A8%D9%85%D8%AF%D9%86-%D8%B4%D9%85%D8%A7%D9%84-%D9%81%D8%B1%D9%86%D8%B3%D8%A7', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 24)
