values ('6dbba605-1b39-4331-813e-b9a97c8ce955', 'world_news', 'rss-6ebcac5a47e5', 'لافروف يبلغ بزشكيان بأن الرئيس بوتين ينتظره في قمة الدول المصدرة للغاز في روسيا', 'أعلن وزير الخارجية الروسي سيرغي لافروف، خلال لقائه الرئيس الإيراني مسعود ببزشكيان، بأن الرئيس بوتين ينتظره في قمة منتدى الدول المصدرة للغاز في موسكو نهاية أكتوبر/تشرين الأول، ويأمل بعقد اجتماع ثنائي معه.', '<p>أعلن وزير الخارجية الروسي سيرغي لافروف، خلال لقائه الرئيس الإيراني مسعود ببزشكيان، بأن الرئيس بوتين ينتظره في قمة منتدى الدول المصدرة للغاز في موسكو نهاية أكتوبر/تشرين الأول، ويأمل بعقد اجتماع ثنائي معه.</p>', 'https://cdn.img.sarabic.ae/img/07ea/0a/0c/1117730866_0:0:2848:1603_600x0_80_0_0_625379e7f9d555508b6b82b0c90f9eae.jpg', 'الصورة من سبوتنيك عربي', 'https://sarabic.ae/20261019/%D9%84%D8%A7%D9%81%D8%B1%D9%88%D9%81-%D9%8A%D8%A8%D9%84%D8%BA-%D8%A8%D8%B2%D8%B4%D9%83%D9%8A%D8%A7%D9%86-%D8%A8%D8%A3%D9%86-%D8%A7%D9%84%D8%B1%D8%A6%D9%8A%D8%B3-%D8%A8%D9%88%D8%AA%D9%8A%D9%86-%D9%8A%D9%86%D8%AA%D8%B8%D8%B1%D9%87-%D9%81%D9%8A-%D9%82%D9%85%D8%A9-%D8%A7%D9%84%D8%AF%D9%88%D9%84-%D8%A7%D9%84%D9%85%D8%B5%D8%AF%D8%B1%D8%A9-%D9%84%D9%84%D8%BA%D8%A7%D8%B2-%D9%81%D9%8A-%D8%B1%D9%88%D8%B3%D9%8A%D8%A7--%D8%B9%D8%A7%D8%AC%D9%84-1117947796.html', 'سبوتنيك عربي', 'https://sarabic.ae/20261019/%D9%84%D8%A7%D9%81%D8%B1%D9%88%D9%81-%D9%8A%D8%A8%D9%84%D8%BA-%D8%A8%D8%B2%D8%B4%D9%83%D9%8A%D8%A7%D9%86-%D8%A8%D8%A3%D9%86-%D8%A7%D9%84%D8%B1%D8%A6%D9%8A%D8%B3-%D8%A8%D9%88%D8%AA%D9%8A%D9%86-%D9%8A%D9%86%D8%AA%D8%B8%D8%B1%D9%87-%D9%81%D9%8A-%D9%82%D9%85%D8%A9-%D8%A7%D9%84%D8%AF%D9%88%D9%84-%D8%A7%D9%84%D9%85%D8%B5%D8%AF%D8%B1%D8%A9-%D9%84%D9%84%D8%BA%D8%A7%D8%B2-%D9%81%D9%8A-%D8%B1%D9%88%D8%B3%D9%8A%D8%A7--%D8%B9%D8%A7%D8%AC%D9%84-1117947796.html', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 23)
