values ('8f0dce6c-b427-1343-66f5-e85336f66fb1', 'world_news', 'rss-181640784f3a', 'نائب رئيس جمعية البيت اللبناني بموسكو يوضح النتائج الاقتصادية لتجميد العقوبات على روسيا', 'قال نائب رئيس جمعية البيت اللبناني في روسيا الاتحادية والأستاذ بالجامعة الروسية للتكنولوجيا، البروفيسور مشعل خداج، أن تجميد عدد من العقوبات على روسيا يعد خطوة مهمة، لما لها من تأثير على الاقتصاد الروسي والاقتصادات الغربية.', '<p>قال نائب رئيس جمعية البيت اللبناني في روسيا الاتحادية والأستاذ بالجامعة الروسية للتكنولوجيا، البروفيسور مشعل خداج، أن تجميد عدد من العقوبات على روسيا يعد خطوة مهمة، لما لها من تأثير على الاقتصاد الروسي والاقتصادات الغربية.</p>', 'https://cdn.img.sarabic.ae/img/07e9/08/0f/1103784036_0:0:2316:1304_600x0_80_0_0_541effff67cc3c7938104de7e3c4a36c.jpg', 'الصورة من سبوتنيك عربي', 'https://sarabic.ae/20261019/%D9%86%D8%A7%D8%A6%D8%A8-%D8%B1%D8%A6%D9%8A%D8%B3-%D8%AC%D9%85%D8%B9%D9%8A%D8%A9-%D8%A7%D9%84%D8%A8%D9%8A%D8%AA-%D8%A7%D9%84%D9%84%D8%A8%D9%86%D8%A7%D9%86%D9%8A-%D8%A8%D9%85%D9%88%D8%B3%D9%83%D9%88-%D9%8A%D9%88%D8%B6%D8%AD-%D8%A7%D9%84%D9%86%D8%AA%D8%A7%D8%A6%D8%AC-%D8%A7%D9%84%D8%A7%D9%82%D8%AA%D8%B5%D8%A7%D8%AF%D9%8A%D8%A9-%D9%84%D8%AA%D8%AC%D9%85%D9%8A%D8%AF-%D8%A7%D9%84%D8%B9%D9%82%D9%88%D8%A8%D8%A7%D8%AA-%D8%B9%D9%84%D9%89-%D8%B1%D9%88%D8%B3%D9%8A%D8%A7-111794745', 'سبوتنيك عربي', 'https://sarabic.ae/20261019/%D9%86%D8%A7%D8%A6%D8%A8-%D8%B1%D8%A6%D9%8A%D8%B3-%D8%AC%D9%85%D8%B9%D9%8A%D8%A9-%D8%A7%D9%84%D8%A8%D9%8A%D8%AA-%D8%A7%D9%84%D9%84%D8%A8%D9%86%D8%A7%D9%86%D9%8A-%D8%A8%D9%85%D9%88%D8%B3%D9%83%D9%88-%D9%8A%D9%88%D8%B6%D8%AD-%D8%A7%D9%84%D9%86%D8%AA%D8%A7%D8%A6%D8%AC-%D8%A7%D9%84%D8%A7%D9%82%D8%AA%D8%B5%D8%A7%D8%AF%D9%8A%D8%A9-%D9%84%D8%AA%D8%AC%D9%85%D9%8A%D8%AF-%D8%A7%D9%84%D8%B9%D9%82%D9%88%D8%A8%D8%A7%D8%AA-%D8%B9%D9%84%D9%89-%D8%B1%D9%88%D8%B3%D9%8A%D8%A7-111794745', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 22)
