values ('0b824321-266c-549c-7a5f-6a9cb620f03c', 'world_news', 'rss-7b93348451a4', 'على الملأ.. نتنياهو ينشر فيديو لـ"مكالمة الدعم" مع ترامب', 'نشر رئيس الوزراء الإسرائيلي بنيامين نتنياهو في حسابه على منصة "إكس"، مساء الإثنين، مقطع فيديو لمكالمة مع الرئيس الأميركي دونالد ترامب، تحمل رسالة دعم قوية من الأخير قبل الانتخابات المرتقبة.', '<p>نشر رئيس الوزراء الإسرائيلي بنيامين نتنياهو في حسابه على منصة "إكس"، مساء الإثنين، مقطع فيديو لمكالمة مع الرئيس الأميركي دونالد ترامب، تحمل رسالة دعم قوية من الأخير قبل الانتخابات المرتقبة.</p>', 'https://images.skynewsarabia.com/images/v1/2026/10/19/1899252/95/53/1-1899252.jpg', 'الصورة من سكاي نيوز عربية', 'https://www.skynewsarabia.com/middle-east/1899254-%D8%A7%D9%84%D9%85%D9%84%D8%A3-%D9%86%D8%AA%D9%86%D9%8A%D8%A7%D9%87%D9%88-%D9%8A%D9%86%D8%B4%D8%B1-%D9%81%D9%8A%D8%AF%D9%8A%D9%88-%D9%84-%D9%85%D9%83%D8%A7%D9%84%D9%85%D8%A9-%D8%A7%D9%84%D8%AF%D8%B9%D9%85-%D8%AA%D8%B1%D8%A7%D9%85%D8%A8', 'سكاي نيوز عربية', 'https://www.skynewsarabia.com/middle-east/1899254-%D8%A7%D9%84%D9%85%D9%84%D8%A3-%D9%86%D8%AA%D9%86%D9%8A%D8%A7%D9%87%D9%88-%D9%8A%D9%86%D8%B4%D8%B1-%D9%81%D9%8A%D8%AF%D9%8A%D9%88-%D9%84-%D9%85%D9%83%D8%A7%D9%84%D9%85%D8%A9-%D8%A7%D9%84%D8%AF%D8%B9%D9%85-%D8%AA%D8%B1%D8%A7%D9%85%D8%A8', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 21)
