values ('bda31faf-b15b-48fe-804f-70e14ddd2f6d', 'world_news', 'rss-8ed6f9a860a4', 'لافروف: روسيا ترحب بتشكيل حلف مكة الدفاعي وتحترم خيار إيران في التعاون معه', 'أعلن وزير الخارجية الروسي سيرغي لافروف ترحيب موسكو بتشكيل حلف مكة الدفاعي بين السعودية وتركيا وباكستان، معتبرا أن أهدافه المعلنة تتمثل في تحقيق الاستقرار وتعزيز السلام والتعاون.', '<p>أعلن وزير الخارجية الروسي سيرغي لافروف ترحيب موسكو بتشكيل حلف مكة الدفاعي بين السعودية وتركيا وباكستان، معتبرا أن أهدافه المعلنة تتمثل في تحقيق الاستقرار وتعزيز السلام والتعاون.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad62b314236042e0e7ac61b.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/world/1844972-%D9%84%D8%A7%D9%81%D8%B1%D9%88%D9%81-%D8%B1%D9%88%D8%B3%D9%8A%D8%A7-%D8%AA%D8%B1%D8%AD%D8%A8-%D8%A8%D8%AA%D8%B4%D9%83%D9%8A%D9%84-%D8%AD%D9%84%D9%81-%D9%85%D9%83%D8%A9-%D8%A7%D9%84%D8%AF%D9%81%D8%A7%D8%B9%D9%8A-%D9%88%D8%AA%D8%AD%D8%AA%D8%B1%D9%85-%D8%AE%D9%8A%D8%A7%D8%B1-%D8%A5%D9%8A%D8%B1%D8%A7%D9%86-%D9%81%D9%8A-%D8%A7%D9%84%D8%AA%D8%B9%D8%A7%D9%88%D9%86-%D9%85%D8%B9%D9%87/', 'روسيا اليوم عربي', 'https://rtarabic.com/world/1844972-%D9%84%D8%A7%D9%81%D8%B1%D9%88%D9%81-%D8%B1%D9%88%D8%B3%D9%8A%D8%A7-%D8%AA%D8%B1%D8%AD%D8%A8-%D8%A8%D8%AA%D8%B4%D9%83%D9%8A%D9%84-%D8%AD%D9%84%D9%81-%D9%85%D9%83%D8%A9-%D8%A7%D9%84%D8%AF%D9%81%D8%A7%D8%B9%D9%8A-%D9%88%D8%AA%D8%AD%D8%AA%D8%B1%D9%85-%D8%AE%D9%8A%D8%A7%D8%B1-%D8%A5%D9%8A%D8%B1%D8%A7%D9%86-%D9%81%D9%8A-%D8%A7%D9%84%D8%AA%D8%B9%D8%A7%D9%88%D9%86-%D9%85%D8%B9%D9%87/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 20)
