values ('22baa585-4c7d-04b3-ae84-dbdadb97dcc8', 'world_news', 'rss-93b540d50e70', 'الدفاع السورية تعلن مقتل جندي بيد مجهولين في ريف دير الزور', 'أعلنت وزارة الدفاع السورية، في بيان لها اليوم الاثنين، مقتل جندي إثر استهدافه من مجهولين بريف دير الزور.', '<p>أعلنت وزارة الدفاع السورية، في بيان لها اليوم الاثنين، مقتل جندي إثر استهدافه من مجهولين بريف دير الزور.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad62aba4c59b70e0a5890f4.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/middle_east/1844975-%D8%A7%D9%84%D8%AF%D9%81%D8%A7%D8%B9-%D8%A7%D9%84%D8%B3%D9%88%D8%B1%D9%8A%D8%A9-%D8%AA%D8%B9%D9%84%D9%86-%D9%85%D9%82%D8%AA%D9%84-%D8%AC%D9%86%D8%AF%D9%8A-%D8%A8%D9%8A%D8%AF-%D9%85%D8%AC%D9%87%D9%88%D9%84%D9%8A%D9%86-%D9%81%D9%8A-%D8%B1%D9%8A%D9%81-%D8%AF%D9%8A%D8%B1-%D8%A7%D9%84%D8%B2%D9%88%D8%B1/', 'روسيا اليوم عربي', 'https://rtarabic.com/middle_east/1844975-%D8%A7%D9%84%D8%AF%D9%81%D8%A7%D8%B9-%D8%A7%D9%84%D8%B3%D9%88%D8%B1%D9%8A%D8%A9-%D8%AA%D8%B9%D9%84%D9%86-%D9%85%D9%82%D8%AA%D9%84-%D8%AC%D9%86%D8%AF%D9%8A-%D8%A8%D9%8A%D8%AF-%D9%85%D8%AC%D9%87%D9%88%D9%84%D9%8A%D9%86-%D9%81%D9%8A-%D8%B1%D9%8A%D9%81-%D8%AF%D9%8A%D8%B1-%D8%A7%D9%84%D8%B2%D9%88%D8%B1/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 18)
