values ('725b2586-9ae8-a603-049d-cf0ac39be66a', 'world_news', 'rss-26e074e04ed7', 'لافروف يكشف الهدف من محاولات دفع القضية الفلسطينية إلى هامش الأجندة الدولية', 'صرح وزير الخارجية الروسي سيرغي لافروف بأن هناك جهودا تُبذل حاليا لدفع القضية الفلسطينية إلى هامش الأجندة الدولية.', '<p>صرح وزير الخارجية الروسي سيرغي لافروف بأن هناك جهودا تُبذل حاليا لدفع القضية الفلسطينية إلى هامش الأجندة الدولية.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad627614c59b70fce51d5f6.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/middle_east/1844970-%D9%84%D8%A7%D9%81%D8%B1%D9%88%D9%81-%D9%8A%D9%83%D8%B4%D9%81-%D8%A7%D9%84%D9%87%D8%AF%D9%81-%D9%85%D9%86-%D9%85%D8%AD%D8%A7%D9%88%D9%84%D8%A7%D8%AA-%D8%AF%D9%81%D8%B9-%D8%A7%D9%84%D9%82%D8%B6%D9%8A%D8%A9-%D8%A7%D9%84%D9%81%D9%84%D8%B3%D8%B7%D9%8A%D9%86%D9%8A%D8%A9-%D8%A5%D9%84%D9%89-%D9%87%D8%A7%D9%85%D8%B4-%D8%A7%D9%84%D8%A3%D8%AC%D9%86%D8%AF%D8%A9-%D8%A7%D9%84%D8%AF%D9%88%D9%84%D9%8A%D8%A9/', 'روسيا اليوم عربي', 'https://rtarabic.com/middle_east/1844970-%D9%84%D8%A7%D9%81%D8%B1%D9%88%D9%81-%D9%8A%D9%83%D8%B4%D9%81-%D8%A7%D9%84%D9%87%D8%AF%D9%81-%D9%85%D9%86-%D9%85%D8%AD%D8%A7%D9%88%D9%84%D8%A7%D8%AA-%D8%AF%D9%81%D8%B9-%D8%A7%D9%84%D9%82%D8%B6%D9%8A%D8%A9-%D8%A7%D9%84%D9%81%D9%84%D8%B3%D8%B7%D9%8A%D9%86%D9%8A%D8%A9-%D8%A5%D9%84%D9%89-%D9%87%D8%A7%D9%85%D8%B4-%D8%A7%D9%84%D8%A3%D8%AC%D9%86%D8%AF%D8%A9-%D8%A7%D9%84%D8%AF%D9%88%D9%84%D9%8A%D8%A9/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 17)
