values ('9c0ca4fb-3365-5905-18c1-f5dd830c3e5a', 'world_news', 'rss-e191e5b6788d', 'دراسة: المشي يوميا يؤدي إلى قرارات ومهارات إدراكية أفضل', 'كشفت دراسة أمريكية حديثة أن ارتفاع عدد الخطوات اليومية يؤدي لأداء أفضل في بعض المهارات الإدراكية، بما في ذلك التركيز المستمر وتجاهل المشتتات والتحكم في القرارات الاندفاعية.', '<p>كشفت دراسة أمريكية حديثة أن ارتفاع عدد الخطوات اليومية يؤدي لأداء أفضل في بعض المهارات الإدراكية، بما في ذلك التركيز المستمر وتجاهل المشتتات والتحكم في القرارات الاندفاعية.</p>', 'https://cdn.img.sarabic.ae/img/07e8/07/19/1091116435_0:47:3072:1775_2072x0_60_0_0_5464b446450b30049c68b3e5dfa2344d.jpg', 'الصورة من سبوتنيك عربي', 'https://sarabic.ae/20261019/%D8%AF%D8%B1%D8%A7%D8%B3%D8%A9-%D8%A7%D9%84%D9%85%D8%B4%D9%8A-%D9%8A%D9%88%D9%85%D9%8A%D8%A7-%D9%8A%D8%A4%D8%AF%D9%8A-%D8%A5%D9%84%D9%89-%D9%82%D8%B1%D8%A7%D8%B1%D8%A7%D8%AA-%D9%88%D9%85%D9%87%D8%A7%D8%B1%D8%A7%D8%AA-%D8%A5%D8%AF%D8%B1%D8%A7%D9%83%D9%8A%D8%A9-%D8%A3%D9%81%D8%B6%D9%84--1117944621.html', 'سبوتنيك عربي', 'https://sarabic.ae/20261019/%D8%AF%D8%B1%D8%A7%D8%B3%D8%A9-%D8%A7%D9%84%D9%85%D8%B4%D9%8A-%D9%8A%D9%88%D9%85%D9%8A%D8%A7-%D9%8A%D8%A4%D8%AF%D9%8A-%D8%A5%D9%84%D9%89-%D9%82%D8%B1%D8%A7%D8%B1%D8%A7%D8%AA-%D9%88%D9%85%D9%87%D8%A7%D8%B1%D8%A7%D8%AA-%D8%A5%D8%AF%D8%B1%D8%A7%D9%83%D9%8A%D8%A9-%D8%A3%D9%81%D8%B6%D9%84--1117944621.html', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 16)
