values ('f7f321c6-2bd9-54b9-cd7f-936c84bc36bc', 'world_news', 'rss-d9afd30958dc', '"البديل من أجل ألمانيا" يعلق على سير قضية تفجير خطوط غاز "السيل الشمالي"', 'في حال تأكد تورط أوكرانيا في تفجير خطوط أنابيب غاز "السيل الشمالي"، سيدان نظام كييف بارتكابه عملا إرهابيا ضد بنية تحتية مدنية، وتعمّده إلحاق الضرر بدول أخرى لتحقيق أهدافه.', '<p>في حال تأكد تورط أوكرانيا في تفجير خطوط أنابيب غاز "السيل الشمالي"، سيدان نظام كييف بارتكابه عملا إرهابيا ضد بنية تحتية مدنية، وتعمّده إلحاق الضرر بدول أخرى لتحقيق أهدافه.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad626a642360430d43af092.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/world/1844969-%D8%A7%D9%84%D8%A8%D8%AF%D9%8A%D9%84-%D9%85%D9%86-%D8%A3%D8%AC%D9%84-%D8%A3%D9%84%D9%85%D8%A7%D9%86%D9%8A%D8%A7-%D9%8A%D8%B9%D9%84%D9%82-%D8%B9%D9%84%D9%89-%D8%B3%D9%8A%D8%B1-%D9%82%D8%B6%D9%8A%D8%A9-%D8%AA%D9%81%D8%AC%D9%8A%D8%B1-%D8%AE%D8%B7%D9%88%D8%B7-%D8%BA%D8%A7%D8%B2-%D8%A7%D9%84%D8%B3%D9%8A%D9%84-%D8%A7%D9%84%D8%B4%D9%85%D8%A7%D9%84%D9%8A/', 'روسيا اليوم عربي', 'https://rtarabic.com/world/1844969-%D8%A7%D9%84%D8%A8%D8%AF%D9%8A%D9%84-%D9%85%D9%86-%D8%A3%D8%AC%D9%84-%D8%A3%D9%84%D9%85%D8%A7%D9%86%D9%8A%D8%A7-%D9%8A%D8%B9%D9%84%D9%82-%D8%B9%D9%84%D9%89-%D8%B3%D9%8A%D8%B1-%D9%82%D8%B6%D9%8A%D8%A9-%D8%AA%D9%81%D8%AC%D9%8A%D8%B1-%D8%AE%D8%B7%D9%88%D8%B7-%D8%BA%D8%A7%D8%B2-%D8%A7%D9%84%D8%B3%D9%8A%D9%84-%D8%A7%D9%84%D8%B4%D9%85%D8%A7%D9%84%D9%8A/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 15)
