values ('856bc970-920f-430b-af7f-d4fd9e0497bc', 'world_news', 'rss-2d2caf0f0bf7', 'روسيا.. هرم من الطراز المصري يزين حدائق كاترين الثانية في ضواحي سانت بطرسبورغ', 'يجسد هرم بطراز مصري في حدائق كاترين الثانية قرب سانت بطرسبورغ افتتان أوروبا في القرن الثامن عشر بالحضارات القديمة، ويكشف جانبا من اهتمام الإمبراطورة الروسية بالآثار والعمارة.', '<p>يجسد هرم بطراز مصري في حدائق كاترين الثانية قرب سانت بطرسبورغ افتتان أوروبا في القرن الثامن عشر بالحضارات القديمة، ويكشف جانبا من اهتمام الإمبراطورة الروسية بالآثار والعمارة.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad613784236042ead184781.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/culture/1844942-%D8%B1%D9%88%D8%B3%D9%8A%D8%A7-%D9%87%D8%B1%D9%85-%D9%85%D9%86-%D8%A7%D9%84%D8%B7%D8%B1%D8%A7%D8%B2-%D8%A7%D9%84%D9%85%D8%B5%D8%B1%D9%8A-%D9%8A%D8%B2%D9%8A%D9%86-%D8%AD%D8%AF%D8%A7%D8%A6%D9%82-%D9%83%D8%A7%D8%AA%D8%B1%D9%8A%D9%86-%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A%D8%A9-%D9%81%D9%8A-%D8%B6%D9%88%D8%A7%D8%AD%D9%8A-%D8%B3%D8%A7%D9%86%D8%AA-%D8%A8%D8%B7%D8%B1%D8%B3%D8%A8%D9%88%D8%B1%D8%BA/', 'روسيا اليوم عربي', 'https://rtarabic.com/culture/1844942-%D8%B1%D9%88%D8%B3%D9%8A%D8%A7-%D9%87%D8%B1%D9%85-%D9%85%D9%86-%D8%A7%D9%84%D8%B7%D8%B1%D8%A7%D8%B2-%D8%A7%D9%84%D9%85%D8%B5%D8%B1%D9%8A-%D9%8A%D8%B2%D9%8A%D9%86-%D8%AD%D8%AF%D8%A7%D8%A6%D9%82-%D9%83%D8%A7%D8%AA%D8%B1%D9%8A%D9%86-%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A%D8%A9-%D9%81%D9%8A-%D8%B6%D9%88%D8%A7%D8%AD%D9%8A-%D8%B3%D8%A7%D9%86%D8%AA-%D8%A8%D8%B7%D8%B1%D8%B3%D8%A8%D9%88%D8%B1%D8%BA/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 14)
