values ('1a7b9ea9-6486-3bc2-63d0-3fe02781ec52', 'world_news', 'rss-738529d014ae', 'بعد مناقشات ماراثونية.. تأجيل حسم التفويض العسكري المصري لدعم السعودية', 'أرجأ مجلس النواب المصري حسم طلب تفويض الرئيس عبد الفتاح السيسي باتخاذ إجراءات عسكرية لدعم السعودية إلى الاثنين المقبل، بعد مناقشات استمرت يومين دون الخروج بقرار نهائي.', '<p>أرجأ مجلس النواب المصري حسم طلب تفويض الرئيس عبد الفتاح السيسي باتخاذ إجراءات عسكرية لدعم السعودية إلى الاثنين المقبل، بعد مناقشات استمرت يومين دون الخروج بقرار نهائي.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad629cb4c59b710175738f6.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/middle_east/1844974-%D8%A8%D8%B9%D8%AF-%D9%85%D9%86%D8%A7%D9%82%D8%B4%D8%A7%D8%AA-%D9%85%D8%A7%D8%B1%D8%A7%D8%AB%D9%88%D9%86%D9%8A%D8%A9-%D8%AA%D8%A3%D8%AC%D9%8A%D9%84-%D8%AD%D8%B3%D9%85-%D8%A7%D9%84%D8%AA%D9%81%D9%88%D9%8A%D8%B6-%D8%A7%D9%84%D8%B9%D8%B3%D9%83%D8%B1%D9%8A-%D8%A7%D9%84%D9%85%D8%B5%D8%B1%D9%8A-%D9%84%D8%AF%D8%B9%D9%85-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9/', 'روسيا اليوم عربي', 'https://rtarabic.com/middle_east/1844974-%D8%A8%D8%B9%D8%AF-%D9%85%D9%86%D8%A7%D9%82%D8%B4%D8%A7%D8%AA-%D9%85%D8%A7%D8%B1%D8%A7%D8%AB%D9%88%D9%86%D9%8A%D8%A9-%D8%AA%D8%A3%D8%AC%D9%8A%D9%84-%D8%AD%D8%B3%D9%85-%D8%A7%D9%84%D8%AA%D9%81%D9%88%D9%8A%D8%B6-%D8%A7%D9%84%D8%B9%D8%B3%D9%83%D8%B1%D9%8A-%D8%A7%D9%84%D9%85%D8%B5%D8%B1%D9%8A-%D9%84%D8%AF%D8%B9%D9%85-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 12)
