values ('48980627-bd89-1ac7-e981-9b87c724e2e6', 'world_news', 'rss-ee146a894f65', 'عراقجي: السياسات الأوروبية الخاطئة تسببت باستمرار الحرب في أوكرانيا', 'اعتبر وزير الخارجية الإيراني، عباس عراقجي، اليوم الاثنين، أن السياسات الأوروبية الخاطئة تسببت باستمرار الحرب في أوكرانيا، مشيرا إلى أن الأوروبيين شركاء في العدوان الأمريكي الإسرائيلي على بلاده.', '<p>اعتبر وزير الخارجية الإيراني، عباس عراقجي، اليوم الاثنين، أن السياسات الأوروبية الخاطئة تسببت باستمرار الحرب في أوكرانيا، مشيرا إلى أن الأوروبيين شركاء في العدوان الأمريكي الإسرائيلي على بلاده.</p>', 'https://cdn.img.sarabic.ae/img/07ea/09/1b/1117320159_0:47:1635:967_2072x0_60_0_0_2b9077b3fe1eab4977b657c76327f228.jpg', 'الصورة من سبوتنيك عربي', 'https://sarabic.ae/20261019/%D8%B9%D8%B1%D8%A7%D9%82%D8%AC%D9%8A-%D8%A7%D9%84%D8%B3%D9%8A%D8%A7%D8%B3%D8%A7%D8%AA-%D8%A7%D9%84%D8%A3%D9%88%D8%B1%D9%88%D8%A8%D9%8A%D8%A9-%D8%A7%D9%84%D8%AE%D8%A7%D8%B7%D8%A6%D8%A9-%D8%AA%D8%B3%D8%A8%D8%A8%D8%AA-%D8%A8%D8%A7%D8%B3%D8%AA%D9%85%D8%B1%D8%A7%D8%B1-%D8%A7%D9%84%D8%AD%D8%B1%D8%A8-%D9%81%D9%8A-%D8%A3%D9%88%D9%83%D8%B1%D8%A7%D9%86%D9%8A%D8%A7-1117943322.html', 'سبوتنيك عربي', 'https://sarabic.ae/20261019/%D8%B9%D8%B1%D8%A7%D9%82%D8%AC%D9%8A-%D8%A7%D9%84%D8%B3%D9%8A%D8%A7%D8%B3%D8%A7%D8%AA-%D8%A7%D9%84%D8%A3%D9%88%D8%B1%D9%88%D8%A8%D9%8A%D8%A9-%D8%A7%D9%84%D8%AE%D8%A7%D8%B7%D8%A6%D8%A9-%D8%AA%D8%B3%D8%A8%D8%A8%D8%AA-%D8%A8%D8%A7%D8%B3%D8%AA%D9%85%D8%B1%D8%A7%D8%B1-%D8%A7%D9%84%D8%AD%D8%B1%D8%A8-%D9%81%D9%8A-%D8%A3%D9%88%D9%83%D8%B1%D8%A7%D9%86%D9%8A%D8%A7-1117943322.html', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 11)
