values ('57097838-e192-60fe-da0f-08d40ce15ed8', 'world_news', 'rss-afe1759124e4', '"مختلة عقليا".. ترامب يشن هجوما على قاضية عرقلت مشروعه', 'هاجم الرئيس الأميركي دونالد ترامب، الإثنين، القاضية الفيدرالية آنا رييس، واصفا إياها بأنها "مختلة عقليا"، بعد إصدارها قرارات قضائية تعرقل خطته لتجديد ملعب إيست بوتوماك للغولف في واشنطن.', '<p>هاجم الرئيس الأميركي دونالد ترامب، الإثنين، القاضية الفيدرالية آنا رييس، واصفا إياها بأنها "مختلة عقليا"، بعد إصدارها قرارات قضائية تعرقل خطته لتجديد ملعب إيست بوتوماك للغولف في واشنطن.</p>', 'https://images.skynewsarabia.com/images/v1/2026/10/19/1899163/95/53/1-1899163.JPG', 'الصورة من سكاي نيوز عربية', 'https://www.skynewsarabia.com/world/1899165-%D9%85%D8%AE%D8%AA%D9%84%D8%A9-%D8%B9%D9%82%D9%84%D9%8A%D8%A7-%D8%AA%D8%B1%D8%A7%D9%85%D8%A8-%D9%8A%D8%B4%D9%86-%D9%87%D8%AC%D9%88%D9%85%D8%A7-%D9%82%D8%A7%D8%B6%D9%8A%D8%A9-%D8%B9%D8%B1%D9%82%D9%84%D8%AA-%D9%85%D8%B4%D8%B1%D9%88%D8%B9%D9%87', 'سكاي نيوز عربية', 'https://www.skynewsarabia.com/world/1899165-%D9%85%D8%AE%D8%AA%D9%84%D8%A9-%D8%B9%D9%82%D9%84%D9%8A%D8%A7-%D8%AA%D8%B1%D8%A7%D9%85%D8%A8-%D9%8A%D8%B4%D9%86-%D9%87%D8%AC%D9%88%D9%85%D8%A7-%D9%82%D8%A7%D8%B6%D9%8A%D8%A9-%D8%B9%D8%B1%D9%82%D9%84%D8%AA-%D9%85%D8%B4%D8%B1%D9%88%D8%B9%D9%87', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 7)
