values ('44b8da17-1749-d6e9-2be1-a6fb13400818', 'world_news', 'rss-aff08a957d16', 'لافروف يؤكد استعداد روسيا للمساعدة في إيجاد حلول للنزاع بين إيران والولايات المتحدة', 'صرح وزير الخارجية الروسي، سيرغي لافروف، بأن بلاده مستعدة للمساعدة في التوصل إلى حلول مقبولة للطرفين لتسوية الأزمة التي نشأت نتيجة العدوان الأمريكي الإسرائيلي ضد إيران.', '<p>صرح وزير الخارجية الروسي، سيرغي لافروف، بأن بلاده مستعدة للمساعدة في التوصل إلى حلول مقبولة للطرفين لتسوية الأزمة التي نشأت نتيجة العدوان الأمريكي الإسرائيلي ضد إيران.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad625184c59b710175738ec.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/world/1844966-%D9%84%D8%A7%D9%81%D8%B1%D9%88%D9%81-%D9%8A%D8%A4%D9%83%D8%AF-%D8%A7%D8%B3%D8%AA%D8%B9%D8%AF%D8%A7%D8%AF-%D8%B1%D9%88%D8%B3%D9%8A%D8%A7-%D9%84%D9%84%D9%85%D8%B3%D8%A7%D8%B9%D8%AF%D8%A9-%D9%81%D9%8A-%D8%A5%D9%8A%D8%AC%D8%A7%D8%AF-%D8%AD%D9%84%D9%88%D9%84-%D9%84%D9%84%D9%86%D8%B2%D8%A7%D8%B9-%D8%A8%D9%8A%D9%86-%D8%A5%D9%8A%D8%B1%D8%A7%D9%86-%D9%88%D8%A7%D9%84%D9%88%D9%84%D8%A7%D9%8A%D8%A7%D8%AA-%D8%A7%D9%84%D9%85%D8%AA%D8%AD%D8%AF%D8%A9/', 'روسيا اليوم عربي', 'https://rtarabic.com/world/1844966-%D9%84%D8%A7%D9%81%D8%B1%D9%88%D9%81-%D9%8A%D8%A4%D9%83%D8%AF-%D8%A7%D8%B3%D8%AA%D8%B9%D8%AF%D8%A7%D8%AF-%D8%B1%D9%88%D8%B3%D9%8A%D8%A7-%D9%84%D9%84%D9%85%D8%B3%D8%A7%D8%B9%D8%AF%D8%A9-%D9%81%D9%8A-%D8%A5%D9%8A%D8%AC%D8%A7%D8%AF-%D8%AD%D9%84%D9%88%D9%84-%D9%84%D9%84%D9%86%D8%B2%D8%A7%D8%B9-%D8%A8%D9%8A%D9%86-%D8%A5%D9%8A%D8%B1%D8%A7%D9%86-%D9%88%D8%A7%D9%84%D9%88%D9%84%D8%A7%D9%8A%D8%A7%D8%AA-%D8%A7%D9%84%D9%85%D8%AA%D8%AD%D8%AF%D8%A9/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 6)
