values ('47f50727-0cd5-3b58-7da6-9af028f3ab6c', 'world_news', 'rss-d0ca9ffa3c09', 'ولية عهد هولندا تحصل على رتبة رقيب في القوات المسلحة', 'أعلن المكتب الإعلامي للديوان الملكي الهولندي أن ولية العهد الأميرة كاترينا أماليا حصلت على رتبة رقيب في القوات المسلحة للمملكة.', '<p>أعلن المكتب الإعلامي للديوان الملكي الهولندي أن ولية العهد الأميرة كاترينا أماليا حصلت على رتبة رقيب في القوات المسلحة للمملكة.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad624ba42360433af417df5.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/society/1844962-%D9%88%D9%84%D9%8A%D8%A9-%D8%B9%D9%87%D8%AF-%D9%87%D9%88%D9%84%D9%86%D8%AF%D8%A7-%D8%AA%D8%AD%D8%B5%D9%84-%D8%B9%D9%84%D9%89-%D8%B1%D8%AA%D8%A8%D8%A9-%D8%B1%D9%82%D9%8A%D8%A8-%D9%81%D9%8A-%D8%A7%D9%84%D9%82%D9%88%D8%A7%D8%AA-%D8%A7%D9%84%D9%85%D8%B3%D9%84%D8%AD%D8%A9/', 'روسيا اليوم عربي', 'https://rtarabic.com/society/1844962-%D9%88%D9%84%D9%8A%D8%A9-%D8%B9%D9%87%D8%AF-%D9%87%D9%88%D9%84%D9%86%D8%AF%D8%A7-%D8%AA%D8%AD%D8%B5%D9%84-%D8%B9%D9%84%D9%89-%D8%B1%D8%AA%D8%A8%D8%A9-%D8%B1%D9%82%D9%8A%D8%A8-%D9%81%D9%8A-%D8%A7%D9%84%D9%82%D9%88%D8%A7%D8%AA-%D8%A7%D9%84%D9%85%D8%B3%D9%84%D8%AD%D8%A9/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 5)
