values ('64628cc2-b3c9-5aeb-79e5-299f1b4cda18', 'world_news', 'rss-bdb20c81365a', 'لافروف: موسكو تناضل من أجل حرية الناطقين بالروسية في أوكرانيا', 'أكد وزير الخارجية الروسي سيرغي لافروف أن روسيا تناضل من أجل حقوق الناطقين بالروسية في أوكرانيا، بينما يسعى نظام كييف إلى تقويض هذه الحقوق.', '<p>أكد وزير الخارجية الروسي سيرغي لافروف أن روسيا تناضل من أجل حقوق الناطقين بالروسية في أوكرانيا، بينما يسعى نظام كييف إلى تقويض هذه الحقوق.</p>', 'https://cdn.img.sarabic.ae/img/07ea/0a/12/1117917220_0:0:1280:721_2072x0_60_0_0_9066780804832f034975241c517184a5.jpg', 'الصورة من سبوتنيك عربي', 'https://sarabic.ae/20261019/%D9%84%D8%A7%D9%81%D8%B1%D9%88%D9%81-%D9%85%D9%88%D8%B3%D9%83%D9%88-%D8%AA%D9%86%D8%A7%D8%B6%D9%84-%D9%85%D9%86-%D8%A3%D8%AC%D9%84-%D8%AD%D8%B1%D9%8A%D8%A9-%D8%A7%D9%84%D9%86%D8%A7%D8%B7%D9%82%D9%8A%D9%86-%D8%A8%D8%A7%D9%84%D8%B1%D9%88%D8%B3%D9%8A%D8%A9-%D9%81%D9%8A-%D8%A3%D9%88%D9%83%D8%B1%D8%A7%D9%86%D9%8A%D8%A7-1117940184.html', 'سبوتنيك عربي', 'https://sarabic.ae/20261019/%D9%84%D8%A7%D9%81%D8%B1%D9%88%D9%81-%D9%85%D9%88%D8%B3%D9%83%D9%88-%D8%AA%D9%86%D8%A7%D8%B6%D9%84-%D9%85%D9%86-%D8%A3%D8%AC%D9%84-%D8%AD%D8%B1%D9%8A%D8%A9-%D8%A7%D9%84%D9%86%D8%A7%D8%B7%D9%82%D9%8A%D9%86-%D8%A8%D8%A7%D9%84%D8%B1%D9%88%D8%B3%D9%8A%D8%A9-%D9%81%D9%8A-%D8%A3%D9%88%D9%83%D8%B1%D8%A7%D9%86%D9%8A%D8%A7-1117940184.html', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 4)
