values ('5a1d762f-63cb-2774-416e-96891ffbe64c', 'world_news', 'rss-2c7b15873a98', 'لافروف: روسيا جاهزة لإيجاد حل مقبول لأزمة إيران', 'أعلن وزير الخارجية الروسي سيرغي لافروف، الإثنين، أن بلاده جاهزة لإيجاد حل مقبول للخروج من الأزمة بين واشنطن وطهران التي طال أمدها.', '<p>أعلن وزير الخارجية الروسي سيرغي لافروف، الإثنين، أن بلاده جاهزة لإيجاد حل مقبول للخروج من الأزمة بين واشنطن وطهران التي طال أمدها.</p>', 'https://images.skynewsarabia.com/images/v1/2026/10/19/1899198/95/53/1-1899198.JPG', 'الصورة من سكاي نيوز عربية', 'https://www.skynewsarabia.com/world/1899199-%D9%84%D8%A7%D9%81%D8%B1%D9%88%D9%81-%D8%B1%D9%88%D8%B3%D9%8A%D8%A7-%D8%AC%D8%A7%D9%87%D8%B2%D8%A9-%D9%84%D8%A5%D9%8A%D8%AC%D8%A7%D8%AF-%D8%AD%D9%84-%D9%85%D9%82%D8%A8%D9%88%D9%84-%D9%84%D8%A3%D8%B2%D9%85%D8%A9-%D8%A5%D9%8A%D8%B1%D8%A7%D9%86', 'سكاي نيوز عربية', 'https://www.skynewsarabia.com/world/1899199-%D9%84%D8%A7%D9%81%D8%B1%D9%88%D9%81-%D8%B1%D9%88%D8%B3%D9%8A%D8%A7-%D8%AC%D8%A7%D9%87%D8%B2%D8%A9-%D9%84%D8%A5%D9%8A%D8%AC%D8%A7%D8%AF-%D8%AD%D9%84-%D9%85%D9%82%D8%A8%D9%88%D9%84-%D9%84%D8%A3%D8%B2%D9%85%D8%A9-%D8%A5%D9%8A%D8%B1%D8%A7%D9%86', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 3)
