values ('c1e4d695-ffac-d0d5-af58-3f042c0b9049', 'world_news', 'rss-c2027dcbf7ba', 'لافروف: الولايات المتحدة وأوروبا من بدأ عملية تقويض استقرار الطاقة العالمي وليس روسيا', 'أعلن وزير الخارجية الروسي سيرغي لافروف، اليوم الإثنين، أن عملية تقويض استقرار الطاقة العالمي لم تبدأها روسيا، بل الاتحاد الأوروبي والولايات المتحدة.', '<p>أعلن وزير الخارجية الروسي سيرغي لافروف، اليوم الإثنين، أن عملية تقويض استقرار الطاقة العالمي لم تبدأها روسيا، بل الاتحاد الأوروبي والولايات المتحدة.</p>', 'https://cdn.img.sarabic.ae/img/07ea/09/18/1117235194_0:0:3072:1728_600x0_80_0_0_0c7e062dfd70102049186c48405df412.jpg', 'الصورة من سبوتنيك عربي', 'https://sarabic.ae/20261019/%D9%84%D8%A7%D9%81%D8%B1%D9%88%D9%81-%D8%A7%D9%84%D9%88%D9%84%D8%A7%D9%8A%D8%A7%D8%AA-%D8%A7%D9%84%D9%85%D8%AA%D8%AD%D8%AF%D8%A9-%D9%88%D8%A3%D9%88%D8%B1%D9%88%D8%A8%D8%A7-%D9%85%D9%86-%D8%A8%D8%AF%D8%A3-%D8%B9%D9%85%D9%84%D9%8A%D8%A9-%D8%AA%D9%82%D9%88%D9%8A%D8%B6-%D8%A7%D8%B3%D8%AA%D9%82%D8%B1%D8%A7%D8%B1-%D8%A7%D9%84%D8%B7%D8%A7%D9%82%D8%A9-%D8%A7%D9%84%D8%B9%D8%A7%D9%84%D9%85%D9%8A-%D9%88%D9%84%D9%8A%D8%B3-%D8%B1%D9%88%D8%B3%D9%8A%D8%A7-1117939891.html', 'سبوتنيك عربي', 'https://sarabic.ae/20261019/%D9%84%D8%A7%D9%81%D8%B1%D9%88%D9%81-%D8%A7%D9%84%D9%88%D9%84%D8%A7%D9%8A%D8%A7%D8%AA-%D8%A7%D9%84%D9%85%D8%AA%D8%AD%D8%AF%D8%A9-%D9%88%D8%A3%D9%88%D8%B1%D9%88%D8%A8%D8%A7-%D9%85%D9%86-%D8%A8%D8%AF%D8%A3-%D8%B9%D9%85%D9%84%D9%8A%D8%A9-%D8%AA%D9%82%D9%88%D9%8A%D8%B6-%D8%A7%D8%B3%D8%AA%D9%82%D8%B1%D8%A7%D8%B1-%D8%A7%D9%84%D8%B7%D8%A7%D9%82%D8%A9-%D8%A7%D9%84%D8%B9%D8%A7%D9%84%D9%85%D9%8A-%D9%88%D9%84%D9%8A%D8%B3-%D8%B1%D9%88%D8%B3%D9%8A%D8%A7-1117939891.html', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 2)
