values ('5fe7af00-f43e-b7bd-d85e-c037393931cd', 'sports', 'rss-8aaeacdd5c41', 'بشكتاش يكتوي بنيران توفان وصلاح (فيديو)', 'حقق فريق طرابزون سبور فوزا ثمينا على ضيفه بشكتاش (2-0) في المباراة التي جمعتهما مساء اليوم الاثنين، وذلك ضمن الجولة الثامنة من الدوري التركي الممتاز لكرة القدم.', '<p>حقق فريق طرابزون سبور فوزا ثمينا على ضيفه بشكتاش (2-0) في المباراة التي جمعتهما مساء اليوم الاثنين، وذلك ضمن الجولة الثامنة من الدوري التركي الممتاز لكرة القدم.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad67a544236045a415f2ebf.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/sport/1845092-%D8%A8%D8%B4%D9%83%D8%AA%D8%A7%D8%B4-%D9%8A%D9%83%D8%AA%D9%88%D9%8A-%D8%A8%D9%86%D9%8A%D8%B1%D8%A7%D9%86-%D8%AA%D9%88%D9%81%D8%A7%D9%86-%D9%88%D8%B5%D9%84%D8%A7%D8%AD-%D9%81%D9%8A%D8%AF%D9%8A%D9%88/', 'روسيا اليوم عربي', 'https://rtarabic.com/sport/1845092-%D8%A8%D8%B4%D9%83%D8%AA%D8%A7%D8%B4-%D9%8A%D9%83%D8%AA%D9%88%D9%8A-%D8%A8%D9%86%D9%8A%D8%B1%D8%A7%D9%86-%D8%AA%D9%88%D9%81%D8%A7%D9%86-%D9%88%D8%B5%D9%84%D8%A7%D8%AD-%D9%81%D9%8A%D8%AF%D9%8A%D9%88/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 60)
