values ('a38509b4-6d69-5d01-73c3-4393109ce5eb', 'sports', 'rss-bcd6f13826a7', 'الفيفا يعاقب حسام وإبراهيم حسن وزيكو', 'أعلن الاتحاد المصري لكرة القدم، الإثنين، تلقيه قرارات من لجنة الانضباط بالاتحاد الدولي "فيفا"، بإيقاف حسام حسن، المدير الفني للمنتخب، وإبراهيم حسن، مدير المنتخب، ثلاث مباريات لكل منهما، واللاعب مصطفى عبد الرؤوف "زيكو" خمس مباريات.', '<p>أعلن الاتحاد المصري لكرة القدم، الإثنين، تلقيه قرارات من لجنة الانضباط بالاتحاد الدولي "فيفا"، بإيقاف حسام حسن، المدير الفني للمنتخب، وإبراهيم حسن، مدير المنتخب، ثلاث مباريات لكل منهما، واللاعب مصطفى عبد الرؤوف "زيكو" خمس مباريات.</p>', 'https://images.skynewsarabia.com/images/v1/2026/10/04/1896114/95/53/1-1896114.jpg', 'الصورة من سكاي نيوز عربية', 'https://www.skynewsarabia.com/sport/1899273-%D8%A7%D9%84%D9%81%D9%8A%D9%81%D8%A7-%D9%8A%D8%B9%D8%A7%D9%82%D8%A8-%D8%AD%D8%B3%D8%A7%D9%85-%D9%88%D8%A5%D8%A8%D8%B1%D8%A7%D9%87%D9%8A%D9%85-%D8%AD%D8%B3%D9%86-%D9%88%D8%B2%D9%8A%D9%83%D9%88', 'سكاي نيوز عربية', 'https://www.skynewsarabia.com/sport/1899273-%D8%A7%D9%84%D9%81%D9%8A%D9%81%D8%A7-%D9%8A%D8%B9%D8%A7%D9%82%D8%A8-%D8%AD%D8%B3%D8%A7%D9%85-%D9%88%D8%A5%D8%A8%D8%B1%D8%A7%D9%87%D9%8A%D9%85-%D8%AD%D8%B3%D9%86-%D9%88%D8%B2%D9%8A%D9%83%D9%88', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 55)
