values ('357d0b3d-0f16-6f31-14d9-aa89b0e95c90', 'sports', 'rss-d12862fc3917', 'شاهد.. صلاح ينتقم من بشكتاش (فيديو)', 'واصل النجم المصري محمد صلاح جناح طرابزون سبور هوايته في تسجيل الأهداف خلال مباراة فريقه ضد ضيفه بشكتاش مساء اليوم الاثنين، ضمن الجولة الثامنة من الدوري التركي الممتاز لكرة القدم.', '<p>واصل النجم المصري محمد صلاح جناح طرابزون سبور هوايته في تسجيل الأهداف خلال مباراة فريقه ضد ضيفه بشكتاش مساء اليوم الاثنين، ضمن الجولة الثامنة من الدوري التركي الممتاز لكرة القدم.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad669f74236045554714764.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/sport/1845072-%D8%B4%D8%A7%D9%87%D8%AF-%D8%B5%D9%84%D8%A7%D8%AD-%D9%8A%D9%86%D8%AA%D9%82%D9%85-%D9%85%D9%86-%D8%A8%D8%B4%D9%83%D8%AA%D8%A7%D8%B4-%D9%81%D9%8A%D8%AF%D9%8A%D9%88/', 'روسيا اليوم عربي', 'https://rtarabic.com/sport/1845072-%D8%B4%D8%A7%D9%87%D8%AF-%D8%B5%D9%84%D8%A7%D8%AD-%D9%8A%D9%86%D8%AA%D9%82%D9%85-%D9%85%D9%86-%D8%A8%D8%B4%D9%83%D8%AA%D8%A7%D8%B4-%D9%81%D9%8A%D8%AF%D9%8A%D9%88/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 54)
