values ('e515cd35-4482-391f-82da-6a434d0c15ef', 'sports', 'rss-93a39267ab5f', 'رسالة من ناصر منسي للزمالك بعد "واقعة القميص"', 'جدد ناصر منسي مهاجم الزمالك المصري، اعتذاره عن رد فعله خلال الاحتفال بهدفه في مرمى الجيش الرواندي، بمباراة ذهاب دور الـ32 لبطولة دوري أبطال إفريقيا.', '<p>جدد ناصر منسي مهاجم الزمالك المصري، اعتذاره عن رد فعله خلال الاحتفال بهدفه في مرمى الجيش الرواندي، بمباراة ذهاب دور الـ32 لبطولة دوري أبطال إفريقيا.</p>', 'https://images.skynewsarabia.com/images/v1/2026/10/19/1899239/95/53/1-1899239.jpg', 'الصورة من سكاي نيوز عربية', 'https://www.skynewsarabia.com/sport/1899240-%D8%B1%D8%B3%D8%A7%D9%84%D8%A9-%D9%86%D8%A7%D8%B5%D8%B1-%D9%85%D9%86%D8%B3%D9%8A-%D9%84%D9%84%D8%B2%D9%85%D8%A7%D9%84%D9%83-%D9%88%D8%A7%D9%82%D8%B9%D8%A9-%D8%A7%D9%84%D9%82%D9%85%D9%8A%D8%B5', 'سكاي نيوز عربية', 'https://www.skynewsarabia.com/sport/1899240-%D8%B1%D8%B3%D8%A7%D9%84%D8%A9-%D9%86%D8%A7%D8%B5%D8%B1-%D9%85%D9%86%D8%B3%D9%8A-%D9%84%D9%84%D8%B2%D9%85%D8%A7%D9%84%D9%83-%D9%88%D8%A7%D9%82%D8%B9%D8%A9-%D8%A7%D9%84%D9%82%D9%85%D9%8A%D8%B5', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 38)
