values ('a910724c-6428-6421-c8be-1f1b61ba9fbf', 'sports', 'rss-bc4cad1da5f9', 'اضطرابات فرنسا تطال كرة القدم.. نهب متجري مرسيليا وليل', 'أعلن ناديا أولمبيك مرسيليا وليل، الإثنين، أن متاجرهما الرسمية تعرضت للنهب خلال الاضطرابات التي شهدتها فرنسا خلال عطلة نهاية الأسبوع.', '<p>أعلن ناديا أولمبيك مرسيليا وليل، الإثنين، أن متاجرهما الرسمية تعرضت للنهب خلال الاضطرابات التي شهدتها فرنسا خلال عطلة نهاية الأسبوع.</p>', 'https://images.skynewsarabia.com/images/v1/2026/10/19/1899230/95/53/1-1899230.jpeg', 'الصورة من سكاي نيوز عربية', 'https://www.skynewsarabia.com/sport/1899232-%D8%A7%D8%B6%D8%B7%D8%B1%D8%A7%D8%A8%D8%A7%D8%AA-%D9%81%D8%B1%D9%86%D8%B3%D8%A7-%D8%AA%D8%B7%D8%A7%D9%84-%D9%83%D8%B1%D8%A9-%D8%A7%D9%84%D9%82%D8%AF%D9%85-%D9%86%D9%87%D8%A8-%D9%85%D8%AA%D8%AC%D8%B1%D9%8A-%D9%85%D8%B1%D8%B3%D9%8A%D9%84%D9%8A%D8%A7-%D9%88%D9%84%D9%8A%D9%84', 'سكاي نيوز عربية', 'https://www.skynewsarabia.com/sport/1899232-%D8%A7%D8%B6%D8%B7%D8%B1%D8%A7%D8%A8%D8%A7%D8%AA-%D9%81%D8%B1%D9%86%D8%B3%D8%A7-%D8%AA%D8%B7%D8%A7%D9%84-%D9%83%D8%B1%D8%A9-%D8%A7%D9%84%D9%82%D8%AF%D9%85-%D9%86%D9%87%D8%A8-%D9%85%D8%AA%D8%AC%D8%B1%D9%8A-%D9%85%D8%B1%D8%B3%D9%8A%D9%84%D9%8A%D8%A7-%D9%88%D9%84%D9%8A%D9%84', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 36)
