values ('0c40ae7e-2319-8085-749c-de7c6ba09286', 'sports', 'rss-dce5c2c931af', 'باريس سان جيرمان ضد برشلونة.. التشكيلة المتوقعة والغيابات وترشيحات الفوز', 'تتجه الأنظار إلى قمة باريس سان جيرمان وبرشلونة في جولة أوروبية مرتقبة، وسط غيابات مؤثرة وتحديات تكتيكية قد تؤدي دورا حاسما في تحديد ملامح المواجهة.', '<p>تتجه الأنظار إلى قمة باريس سان جيرمان وبرشلونة في جولة أوروبية مرتقبة، وسط غيابات مؤثرة وتحديات تكتيكية قد تؤدي دورا حاسما في تحديد ملامح المواجهة.</p>', null, null, 'https://www.aljazeera.net/sport/2026/10/19/%d8%a8%d8%a7%d8%b1%d9%8a%d8%b3-%d8%b3%d8%a7%d9%86-%d8%ac%d9%8a%d8%b1%d9%85%d8%a7%d9%86-%d8%b6%d8%af-%d8%a8%d8%b1%d8%b4%d9%84%d9%88%d9%86%d8%a9', 'الجزيرة نت', 'https://www.aljazeera.net/sport/2026/10/19/%d8%a8%d8%a7%d8%b1%d9%8a%d8%b3-%d8%b3%d8%a7%d9%86-%d8%ac%d9%8a%d8%b1%d9%85%d8%a7%d9%86-%d8%b6%d8%af-%d8%a8%d8%b1%d8%b4%d9%84%d9%88%d9%86%d8%a9', '["رياضة"]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 35)
