values ('4c2f0a0f-67a3-6fff-3ba6-cfb856e959ce', 'sports', 'rss-17116fdfc079', '255 يورو غرامة.. الاتحاد البرتغالي يكشف تفاصيل عقوبة رونالدو', 'تطور جديد في قضية كريستيانو رونالدو مع منتخب البرتغال قد يرسم ملامح المرحلة المقبلة من علاقته بالمنتخب ومدربه جورجي جيسوس.', '<p>تطور جديد في قضية كريستيانو رونالدو مع منتخب البرتغال قد يرسم ملامح المرحلة المقبلة من علاقته بالمنتخب ومدربه جورجي جيسوس.</p>', null, null, 'https://www.aljazeera.net/sport/2026/10/19/%d9%83%d8%b1%d9%8a%d8%b3%d8%aa%d9%8a%d8%a7%d9%86%d9%88-%d8%b1%d9%88%d9%86%d8%a7%d9%84%d8%af%d9%88-%d8%a7%d9%84%d8%a8%d8%b1%d8%aa%d8%ba%d8%a7%d9%84-%d8%b9%d9%82%d9%88%d8%a8%d8%a9', 'الجزيرة نت', 'https://www.aljazeera.net/sport/2026/10/19/%d9%83%d8%b1%d9%8a%d8%b3%d8%aa%d9%8a%d8%a7%d9%86%d9%88-%d8%b1%d9%88%d9%86%d8%a7%d9%84%d8%af%d9%88-%d8%a7%d9%84%d8%a8%d8%b1%d8%aa%d8%ba%d8%a7%d9%84-%d8%b9%d9%82%d9%88%d8%a8%d8%a9', '["رياضة"]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 34)
