values ('a92c6c71-88f6-83f6-6b37-dbbbfc7a9d47', 'sports', 'rss-5a88955ccf5b', 'متاحة عبر المتجر الإلكتروني.. طرابزون سبور يطرح مجموعة خاصة تحمل اسم صلاح (فيديو)', 'أعلن نادي طرابزون سبور التركي لكرة القدم، طرح مجموعة خاصة تحمل اسم نجمه المصري محمد صلاح، في خطوة تستهدف جماهير اللاعب المصري ومحبي النادي.', '<p>أعلن نادي طرابزون سبور التركي لكرة القدم، طرح مجموعة خاصة تحمل اسم نجمه المصري محمد صلاح، في خطوة تستهدف جماهير اللاعب المصري ومحبي النادي.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad61b7c4236042ea86d9af5.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/sport/1844929-%D9%85%D8%AA%D8%A7%D8%AD%D8%A9-%D8%B9%D8%A8%D8%B1-%D8%A7%D9%84%D9%85%D8%AA%D8%AC%D8%B1-%D8%A7%D9%84%D8%A5%D9%84%D9%83%D8%AA%D8%B1%D9%88%D9%86%D9%8A-%D8%B7%D8%B1%D8%A7%D8%A8%D8%B2%D9%88%D9%86-%D8%B3%D8%A8%D9%88%D8%B1-%D9%8A%D8%B7%D8%B1%D8%AD-%D9%85%D8%AC%D9%85%D9%88%D8%B9%D8%A9-%D8%AE%D8%A7%D8%B5%D8%A9-%D8%AA%D8%AD%D9%85%D9%84-%D8%A7%D8%B3%D9%85-%D8%B5%D9%84%D8%A7%D8%AD-%D9%81%D9%8A%D8%AF%D9%8A%D9%88/', 'روسيا اليوم عربي', 'https://rtarabic.com/sport/1844929-%D9%85%D8%AA%D8%A7%D8%AD%D8%A9-%D8%B9%D8%A8%D8%B1-%D8%A7%D9%84%D9%85%D8%AA%D8%AC%D8%B1-%D8%A7%D9%84%D8%A5%D9%84%D9%83%D8%AA%D8%B1%D9%88%D9%86%D9%8A-%D8%B7%D8%B1%D8%A7%D8%A8%D8%B2%D9%88%D9%86-%D8%B3%D8%A8%D9%88%D8%B1-%D9%8A%D8%B7%D8%B1%D8%AD-%D9%85%D8%AC%D9%85%D9%88%D8%B9%D8%A9-%D8%AE%D8%A7%D8%B5%D8%A9-%D8%AA%D8%AD%D9%85%D9%84-%D8%A7%D8%B3%D9%85-%D8%B5%D9%84%D8%A7%D8%AD-%D9%81%D9%8A%D8%AF%D9%8A%D9%88/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 25)
