values ('8c73c018-336f-3343-f527-f91f4a174ecf', 'sports', 'rss-17879f5bdb7a', '"مازادونا".. ليفركوزن يحتفي بمهارات نجمه الجزائري إبراهيم مازة (فيديو)', 'أشاد نادي باير ليفركوزن الألماني بالأداء الاستثنائي لنجمه الجزائري إبراهيم مازة بعد قيادته الفريق للفوز على فرايبورغ بتسجيل هدف وصناعة آخر بطريقة ساحرة.', '<p>أشاد نادي باير ليفركوزن الألماني بالأداء الاستثنائي لنجمه الجزائري إبراهيم مازة بعد قيادته الفريق للفوز على فرايبورغ بتسجيل هدف وصناعة آخر بطريقة ساحرة.</p>', null, null, 'https://www.aljazeera.net/sport/2026/10/19/%d9%85%d8%a7%d8%b2%d8%a7%d8%af%d9%88%d9%86%d8%a7-%d9%84%d9%8a%d9%81%d8%b1%d9%83%d9%88%d8%b2%d9%86-%d8%a7%d9%84%d8%ac%d8%b2%d8%a7%d8%a6%d8%b1%d9%8a-%d9%85%d8%a7%d8%b2%d8%a9', 'الجزيرة نت', 'https://www.aljazeera.net/sport/2026/10/19/%d9%85%d8%a7%d8%b2%d8%a7%d8%af%d9%88%d9%86%d8%a7-%d9%84%d9%8a%d9%81%d8%b1%d9%83%d9%88%d8%b2%d9%86-%d8%a7%d9%84%d8%ac%d8%b2%d8%a7%d8%a6%d8%b1%d9%8a-%d9%85%d8%a7%d8%b2%d8%a9', '["رياضة"]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 16)
