values ('eac8f4f3-490b-1217-09d6-1537c4b6b825', 'sports', 'rss-ea4a66672907', '5 فرق على القمة.. الدوري الفرنسي يسجل سابقة تاريخية', 'يشهد الدوري الفرنسي لكرة القدم بداية استثنائية للموسم الحالي بعد مرور 7 جولات، في حين شهدت مباريات الأسبوع الأخير احتساب 4 ركلات جزاء.', '<p>يشهد الدوري الفرنسي لكرة القدم بداية استثنائية للموسم الحالي بعد مرور 7 جولات، في حين شهدت مباريات الأسبوع الأخير احتساب 4 ركلات جزاء.</p>', null, null, 'https://www.aljazeera.net/sport/2026/10/19/5-%d9%81%d8%b1%d9%82-%d8%b9%d9%84%d9%89-%d8%a7%d9%84%d9%82%d9%85%d8%a9-%d8%a7%d9%84%d8%af%d9%88%d8%b1%d9%8a-%d8%a7%d9%84%d9%81%d8%b1%d9%86%d8%b3%d9%8a-%d9%8a%d8%b3%d8%ac%d9%84', 'الجزيرة نت', 'https://www.aljazeera.net/sport/2026/10/19/5-%d9%81%d8%b1%d9%82-%d8%b9%d9%84%d9%89-%d8%a7%d9%84%d9%82%d9%85%d8%a9-%d8%a7%d9%84%d8%af%d9%88%d8%b1%d9%8a-%d8%a7%d9%84%d9%81%d8%b1%d9%86%d8%b3%d9%8a-%d9%8a%d8%b3%d8%ac%d9%84', '["رياضة"]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 14)
