values ('a75e3034-b397-bc17-6fbc-3aab3851ba25', 'sports', 'rss-6f99c5ca3e44', '"ليون" يقلب الطاولة ويتصدر الدوري الفرنسي بفارق الأهداف', 'حقق أولمبيك ليون فوزا ثمينا على ضيفه نيس بنتيجة 2-1، ليعتلي بذلك صدارة جدول ترتيب الدوري الفرنسي لكرة القدم، مستفيدا من فارق الأهداف في ظل تقارب النقاط بين الفرق المتنافسة.', '<p>حقق أولمبيك ليون فوزا ثمينا على ضيفه نيس بنتيجة 2-1، ليعتلي بذلك صدارة جدول ترتيب الدوري الفرنسي لكرة القدم، مستفيدا من فارق الأهداف في ظل تقارب النقاط بين الفرق المتنافسة.</p>', 'https://images.skynewsarabia.com/images/v1/2026/10/19/1899000/95/53/1-1899000.jpg', 'الصورة من سكاي نيوز عربية', 'https://www.skynewsarabia.com/sport/1899001-%D9%84%D9%8A%D9%88%D9%86-%D9%8A%D9%82%D9%84%D8%A8-%D8%A7%D9%84%D8%B7%D8%A7%D9%88%D9%84%D8%A9-%D9%88%D9%8A%D8%AA%D8%B5%D8%AF%D8%B1-%D8%A7%D9%84%D8%AF%D9%88%D8%B1%D9%8A-%D8%A7%D9%84%D9%81%D8%B1%D9%86%D8%B3%D9%8A-%D8%A8%D9%81%D8%A7%D8%B1%D9%82-%D8%A7%D9%84%D8%A3%D9%87%D8%AF%D8%A7%D9%81', 'سكاي نيوز عربية', 'https://www.skynewsarabia.com/sport/1899001-%D9%84%D9%8A%D9%88%D9%86-%D9%8A%D9%82%D9%84%D8%A8-%D8%A7%D9%84%D8%B7%D8%A7%D9%88%D9%84%D8%A9-%D9%88%D9%8A%D8%AA%D8%B5%D8%AF%D8%B1-%D8%A7%D9%84%D8%AF%D9%88%D8%B1%D9%8A-%D8%A7%D9%84%D9%81%D8%B1%D9%86%D8%B3%D9%8A-%D8%A8%D9%81%D8%A7%D8%B1%D9%82-%D8%A7%D9%84%D8%A3%D9%87%D8%AF%D8%A7%D9%81', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-19', '2026-10-19T00:00:00.000Z'::timestamptz, 11)
