values ('7fb0b568-89b6-bdc6-bbe2-8df8c148ac38', 'sports', 'rss-beaa09e3f331', 'تسديدة "صاروخية" من منتصف المعلب.. دييغو غوميز يسجل هدف الموسم في الدوري الإنجليزي', 'خطف الباراغواياني دييغو غوميز لاعب وسط برايتون، الأضواء بعدما سجل أحد أجمل أهداف الموسم في الدوري الإنجليزي الممتاز، ليقود فريقه لفوز ساحق على ضيفه كريستال بالاس 5-0 مساء الأحد.', '<p>خطف الباراغواياني دييغو غوميز لاعب وسط برايتون، الأضواء بعدما سجل أحد أجمل أهداف الموسم في الدوري الإنجليزي الممتاز، ليقود فريقه لفوز ساحق على ضيفه كريستال بالاس 5-0 مساء الأحد.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad5461142360450fe77866f.png', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/sport/1844713-%D8%AA%D8%B3%D8%AF%D9%8A%D8%AF%D8%A9-%D8%B5%D8%A7%D8%B1%D9%88%D8%AE%D9%8A%D8%A9-%D9%85%D9%86-%D9%85%D9%86%D8%AA%D8%B5%D9%81-%D8%A7%D9%84%D9%85%D8%B9%D9%84%D8%A8-%D8%AF%D9%8A%D9%8A%D8%BA%D9%88-%D8%BA%D9%88%D9%85%D9%8A%D8%B2-%D9%8A%D8%B3%D8%AC%D9%84-%D9%87%D8%AF%D9%81-%D8%A7%D9%84%D9%85%D9%88%D8%B3%D9%85-%D9%81%D9%8A-%D8%A7%D9%84%D8%AF%D9%88%D8%B1%D9%8A-%D8%A7%D9%84%D8%A5%D9%86%D8%AC%D9%84%D9%8A%D8%B2%D9%8A/', 'روسيا اليوم عربي', 'https://rtarabic.com/sport/1844713-%D8%AA%D8%B3%D8%AF%D9%8A%D8%AF%D8%A9-%D8%B5%D8%A7%D8%B1%D9%88%D8%AE%D9%8A%D8%A9-%D9%85%D9%86-%D9%85%D9%86%D8%AA%D8%B5%D9%81-%D8%A7%D9%84%D9%85%D8%B9%D9%84%D8%A8-%D8%AF%D9%8A%D9%8A%D8%BA%D9%88-%D8%BA%D9%88%D9%85%D9%8A%D8%B2-%D9%8A%D8%B3%D8%AC%D9%84-%D9%87%D8%AF%D9%81-%D8%A7%D9%84%D9%85%D9%88%D8%B3%D9%85-%D9%81%D9%8A-%D8%A7%D9%84%D8%AF%D9%88%D8%B1%D9%8A-%D8%A7%D9%84%D8%A5%D9%86%D8%AC%D9%84%D9%8A%D8%B2%D9%8A/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-18', '2026-10-18T00:00:00.000Z'::timestamptz, 10)
