values ('85d8735f-ccc7-e4c6-ec9d-b5411383668f', 'sports', 'rss-6571c78eeb2c', 'لاتسيو يواصل مزاحمة إنتر في صدارة الدوري الإيطالي بفوز كبير على يوفنتوس', 'واصل لاتسيو مزاحمته للمتصدر إنتر ميلان وحقق فوزا عريضا ومستحقا على مضيفه يوفنتوس بثلاثية نظيفة مساء الأحد، ضمن منافسات الجولة السابعة من الدوري الإيطالي لكرة القدم.', '<p>واصل لاتسيو مزاحمته للمتصدر إنتر ميلان وحقق فوزا عريضا ومستحقا على مضيفه يوفنتوس بثلاثية نظيفة مساء الأحد، ضمن منافسات الجولة السابعة من الدوري الإيطالي لكرة القدم.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad548c34236044daf1f36cd.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/sport/1844719-%D9%84%D8%A7%D8%AA%D8%B3%D9%8A%D9%88-%D9%8A%D9%88%D8%A7%D8%B5%D9%84-%D9%85%D8%B2%D8%A7%D8%AD%D9%85%D8%A9-%D8%A5%D9%86%D8%AA%D8%B1-%D9%81%D9%8A-%D8%B5%D8%AF%D8%A7%D8%B1%D8%A9-%D8%A7%D9%84%D8%AF%D9%88%D8%B1%D9%8A-%D8%A7%D9%84%D8%A5%D9%8A%D8%B7%D8%A7%D9%84%D9%8A-%D8%A8%D9%81%D9%88%D8%B2-%D9%83%D8%A8%D9%8A%D8%B1-%D8%B9%D9%84%D9%89-%D9%8A%D9%88%D9%81%D9%86%D8%AA%D9%88%D8%B3/', 'روسيا اليوم عربي', 'https://rtarabic.com/sport/1844719-%D9%84%D8%A7%D8%AA%D8%B3%D9%8A%D9%88-%D9%8A%D9%88%D8%A7%D8%B5%D9%84-%D9%85%D8%B2%D8%A7%D8%AD%D9%85%D8%A9-%D8%A5%D9%86%D8%AA%D8%B1-%D9%81%D9%8A-%D8%B5%D8%AF%D8%A7%D8%B1%D8%A9-%D8%A7%D9%84%D8%AF%D9%88%D8%B1%D9%8A-%D8%A7%D9%84%D8%A5%D9%8A%D8%B7%D8%A7%D9%84%D9%8A-%D8%A8%D9%81%D9%88%D8%B2-%D9%83%D8%A8%D9%8A%D8%B1-%D8%B9%D9%84%D9%89-%D9%8A%D9%88%D9%81%D9%86%D8%AA%D9%88%D8%B3/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-18', '2026-10-18T00:00:00.000Z'::timestamptz, 9)
