values ('69c28c47-68b1-1d7c-2a07-c5e5188e2a40', 'sports', 'rss-d1e423444ba5', 'ريال مدريد يتخطى إشبيلية برباعية ويصعد إلى المركز الثالث في ترتيب "الليغا"', 'قدم ريال مدريد عرضا هجوميا قويا ليحسم مواجهته أمام ضيفه إشبيلية بنتيجة 4-1 مساء الأحد، لحساب الجولة التاسعة من الدوري الإسباني لكرة القدم.', '<p>قدم ريال مدريد عرضا هجوميا قويا ليحسم مواجهته أمام ضيفه إشبيلية بنتيجة 4-1 مساء الأحد، لحساب الجولة التاسعة من الدوري الإسباني لكرة القدم.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad53ca34236044e8663817b.jpg', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/sport/1844706-%D8%B1%D9%8A%D8%A7%D9%84-%D9%85%D8%AF%D8%B1%D9%8A%D8%AF-%D9%8A%D8%AA%D8%AE%D8%B7%D9%89-%D8%A5%D8%B4%D8%A8%D9%8A%D9%84%D9%8A%D8%A9-%D8%A8%D8%B1%D8%A8%D8%A7%D8%B9%D9%8A%D8%A9-%D9%88%D9%8A%D8%B5%D8%B9%D8%AF-%D8%A5%D9%84%D9%89-%D8%A7%D9%84%D9%85%D8%B1%D9%83%D8%B2-%D8%A7%D9%84%D8%AB%D8%A7%D9%84%D8%AB-%D9%81%D9%8A-%D8%AA%D8%B1%D8%AA%D9%8A%D8%A8-%D8%A7%D9%84%D9%84%D9%8A%D8%BA%D8%A7/', 'روسيا اليوم عربي', 'https://rtarabic.com/sport/1844706-%D8%B1%D9%8A%D8%A7%D9%84-%D9%85%D8%AF%D8%B1%D9%8A%D8%AF-%D9%8A%D8%AA%D8%AE%D8%B7%D9%89-%D8%A5%D8%B4%D8%A8%D9%8A%D9%84%D9%8A%D8%A9-%D8%A8%D8%B1%D8%A8%D8%A7%D8%B9%D9%8A%D8%A9-%D9%88%D9%8A%D8%B5%D8%B9%D8%AF-%D8%A5%D9%84%D9%89-%D8%A7%D9%84%D9%85%D8%B1%D9%83%D8%B2-%D8%A7%D9%84%D8%AB%D8%A7%D9%84%D8%AB-%D9%81%D9%8A-%D8%AA%D8%B1%D8%AA%D9%8A%D8%A8-%D8%A7%D9%84%D9%84%D9%8A%D8%BA%D8%A7/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-18', '2026-10-18T00:00:00.000Z'::timestamptz, 4)
