values ('4dfc226c-03ac-9e5e-c807-666581a6f6cb', 'sports', 'rss-4b5d92531802', 'هدية تركية استثنائية لرئيس الوزراء المصري.. ومحمد صلاح في قلب المشهد!', 'تلقى مصطفى مدبولي رئيس مجلس الوزراء المصري هدية مفاجئة خلال زيارته معرض "تراثنا 2026" بالقاهرة الجديدة، تمثلت في قميص نادي طرابزون سبور التركي يحمل اسم النجم المصري محمد صلاح.', '<p>تلقى مصطفى مدبولي رئيس مجلس الوزراء المصري هدية مفاجئة خلال زيارته معرض "تراثنا 2026" بالقاهرة الجديدة، تمثلت في قميص نادي طرابزون سبور التركي يحمل اسم النجم المصري محمد صلاح.</p>', 'https://cdnv.russiatoday.com/media/pics/2026.10/thumbnail/6ad539e54c59b76c9a360986.png', 'الصورة من روسيا اليوم عربي', 'https://rtarabic.com/sport/1844701-%D9%87%D8%AF%D9%8A%D8%A9-%D8%AA%D8%B1%D9%83%D9%8A%D8%A9-%D8%A7%D8%B3%D8%AA%D8%AB%D9%86%D8%A7%D8%A6%D9%8A%D8%A9-%D9%84%D8%B1%D8%A6%D9%8A%D8%B3-%D8%A7%D9%84%D9%88%D8%B2%D8%B1%D8%A7%D8%A1-%D8%A7%D9%84%D9%85%D8%B5%D8%B1%D9%8A-%D9%88%D9%85%D8%AD%D9%85%D8%AF-%D8%B5%D9%84%D8%A7%D8%AD-%D9%81%D9%8A-%D9%82%D9%84%D8%A8-%D8%A7%D9%84%D9%85%D8%B4%D9%87%D8%AF/', 'روسيا اليوم عربي', 'https://rtarabic.com/sport/1844701-%D9%87%D8%AF%D9%8A%D8%A9-%D8%AA%D8%B1%D9%83%D9%8A%D8%A9-%D8%A7%D8%B3%D8%AA%D8%AB%D9%86%D8%A7%D8%A6%D9%8A%D8%A9-%D9%84%D8%B1%D8%A6%D9%8A%D8%B3-%D8%A7%D9%84%D9%88%D8%B2%D8%B1%D8%A7%D8%A1-%D8%A7%D9%84%D9%85%D8%B5%D8%B1%D9%8A-%D9%88%D9%85%D8%AD%D9%85%D8%AF-%D8%B5%D9%84%D8%A7%D8%AD-%D9%81%D9%8A-%D9%82%D9%84%D8%A8-%D8%A7%D9%84%D9%85%D8%B4%D9%87%D8%AF/', '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-18', '2026-10-18T00:00:00.000Z'::timestamptz, 3)
