values ('8d7890da-6edd-e5e9-2637-188120c59b78', 'my_apps', 'ketabu-raby', 'القران حياتي', 'القرآن الكريم بأصوات أشهر القراء، مع أوقات الصلاة والأذكار والتفسير واتجاه القبلة', '<p>تطبيق «كتاب رابي» رفيق إسلامي متكامل: قراءة القرآن الكريم بخط عثماني واضح مع تفسير مدمج وأصوات متعددة للقراء، وأوقات الصلاة المحسوبة بدقة حسب موقعك مع إشعارات الأذان، والأذكار الصباحية والمسائية والنوم، إلى جانب البحث في القرآن والإشارات المرجعية وسجل القراءة واتجاه القبلة وعداد التسبيح والمتشابهات القرآنية ومواضيع قرآنية مختارة. يتميز بوضع ليلي مريح للعين وخطوط قابلة للتخصيص، ويعمل بدون إنترنت بعد تحميل البيانات.</p>', 'https://play-lh.googleusercontent.com/KxRd1Ie31XGwkTwn65iyWirvKILatU2KmbEO-LvaPds_QQwPxGLz9uH1OkAkP-SF4g08S1wy19GJLdjDxYSlllM=w192-h192-rw', null, 'https://play.google.com/store/apps/details?id=ketabu.raby&hl=ar', 'Google Play', 'https://play.google.com/store/apps/details?id=ketabu.raby&hl=ar', '[]'::jsonb, '{"الحزمة":"ketabu.raby","المطوّر":"Desho.Co.Ltd","المميزات":"خط عثماني واضح مع تفسير مدمج، أصوات متعددة للقراء، أوقات الصلاة مع إشعار الأذان، الأذكار الصباحية والمسائية والنوم، اتجاه القبلة وعداد التسبيح، وضع ليلي وخطوط قابلة للتخصيص، يعمل بدون إنترنت بعد تحميل البيانات","آخر تحديث":"2026-09-28"}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-04', '2026-10-04T00:00:00.000Z'::timestamptz, 19)
