values ('c456f9fe-08e0-63e0-a5fd-4b74a6914ef6', 'code_channels', 'junior-coders', 'جنيور كودرز — Junior Coders', 'برمجة للأطفال بطريقة سهلة وسلسة، مع أنشطة تُعمل في البيت', '<p>قناة تشرح أساسيات البرمجة للأطفال بأسلوب مبسّط، وهدفها مساعدة الأهل على شرح البرمجة لأبنائهم مع إتاحة متابعة الطفل للفيديوهات بنفسه. فيها قائمة «Programming for kids (Hour of code)» للأنشطة الرقمية، وقائمة «Unplugged Programming activities for kids» أنشطة برمجة بلا شاشة تُنفَّذ بالورقة والقلم.</p>', null, null, 'https://www.youtube.com/@TheHend1986', 'يوتيوب', 'https://www.youtube.com/@TheHend1986', '["أنشطة بلا شاشة","ساعة البرمجة","مع الأهل"]'::jsonb, '{"اللغة":"العربية","معرّف القناة":"UC4hlEHtJ2sBwTSBqt5-ZayA","الفئة العمرية":"الأطفال مع الأهل"}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-04', '2026-10-04T00:00:00.000Z'::timestamptz, 6)
on conflict (id) do nothing;
