values ('4e8b8d53-a323-3599-ecae-03ed5988b772', 'code_channels', 'safaa-elshafey', 'برمجة للأطفال — صفاء الشافعي', 'كورسات سكراتش وأساسيات الكمبيوتر بالعربي من الصفر', '<p>قناة متخصصة في تعليم البرمجة في سن مبكرة، تشرح من الصفر بأسلوب مبسّط. يقسَّم محتواها إلى مسارات معلومة العمر، منها «أساسيات الكمبيوتر» من السادسة إلى السادسة عشرة، ومسار «The Journeys» من الثامنة إلى السادسة عشرة في أساسيات الويب، إلى جانب دروس سكراتش بالعربي.</p>', null, null, 'https://www.youtube.com/@SafaaElShafey', 'يوتيوب', 'https://www.youtube.com/@SafaaElShafey', '["سكراتش","أساسيات الكمبيوتر","ويب للمبتدئين"]'::jsonb, '{"اللغة":"العربية","معرّف القناة":"UCC_bGf8JdzCef1ubGK8yYyA","الفئة العمرية":"من ٦ إلى ١٦ سنة"}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-04', '2026-10-04T00:00:00.000Z'::timestamptz, 5)
on conflict (id) do nothing;
