values ('d92c264f-2156-26fd-03df-27d6f3801346', 'code_channels', 'little-coder', 'ليتل كودر — Little Coder', '«علّموا أولادكم البرمجة»: دروس ومشاريع للأطفال بالعربي', '<p>قناة تنطلق من أن البرمجة صارت لغة أساسية تدخل المناهج، فتعلّم الأطفال خطوة خطوة بمشاريع صغيرة، وتقدّم أيضًا محتوى لإعداد مدرّبي برمجة للأطفال — ما يجعلها مفيدة للأهل والمعلّمين الذين يريدون ورشة صيفية في القرية.</p>', null, null, 'https://www.youtube.com/@LittleCoder', 'يوتيوب', 'https://www.youtube.com/@LittleCoder', '["مشاريع للأطفال","سكراتش","إعداد مدرّبين"]'::jsonb, '{"اللغة":"العربية","معرّف القناة":"UCK4EAMITJEmO0lgEMdy8EYw","الفئة العمرية":"الأطفال"}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-04', '2026-10-04T00:00:00.000Z'::timestamptz, 4)
on conflict (id) do nothing;
