values ('3533682c-2da1-9d62-e2b2-c9351e4f2d4f', 'code_channels', 'samar-kids-camp', 'سامار كيدز كامب — SAMAR KIDS CAMP', 'كورس سكراتش للأطفال بالعربي مع أنشطة تعليمية عامة', '<p>قناة تستهدف تعليم الأطفال في جوانب دينية وأخلاقية وتعليمية معًا، ومنها كورس سكراتش بالعربي بمقدمة مبسّطة للصغار. تصلح لمن يريد محتوى طفوليًّا خفيفًا لا برمجة وحدها.</p>', null, null, 'https://www.youtube.com/@samarsamy1145', 'يوتيوب', 'https://www.youtube.com/@samarsamy1145', '["سكراتش","أنشطة للأطفال","تعليم عام"]'::jsonb, '{"اللغة":"العربية","معرّف القناة":"UCjqlJ986W6jJzIcUK3CMhjA","الفئة العمرية":"الأطفال"}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-04', '2026-10-04T00:00:00.000Z'::timestamptz, 3)
on conflict (id) do nothing;
