values ('987b8aa4-e8a0-6cba-c9a5-9f9f73640e1b', 'code_channels', 'robotics-for-kids', 'روبوتكس للأطفال — Robotics for kids', 'من البرمجة إلى صناعة الروبوت: أساسيات للأطفال والمبتدئين', '<p>قناة متخصصة بعلوم الروبوت، تساعد الأطفال والمبتدئين على تعلّم أساسيات صناعة الروبوت خطوة خطوة. وهي الأنسب لمن أنهى أساسيات سكراتش وأراد الانتقال إلى أجهزة حقيقية وبرمجة الحركة والحسّاسات.</p>', null, null, 'https://www.youtube.com/@roboticsforkids2023', 'يوتيوب', 'https://www.youtube.com/@roboticsforkids2023', '["روبوتكس","إلكترونيات","برمجة الأجهزة"]'::jsonb, '{"اللغة":"العربية","معرّف القناة":"UCtoPvUaO2fix6Rzdvu5GUnQ","الفئة العمرية":"الأطفال والمبتدئون"}'::jsonb, '[]'::jsonb, false, false, 'published', '2026-10-04', '2026-10-04T00:00:00.000Z'::timestamptz, 2)
on conflict (id) do nothing;
